local config = {
  ui_story_5026_50260101_1_dialog_content = "PlayerName, PlayerName?",
  ui_story_5026_50260101_2_dialog_content = "Hey! It's well past time for you to wake up!",
  ui_story_5026_50260101_3_dialog_content = "(Who's that talking?)",
  ui_story_5026_50260101_4_dialog_content = "The prize redemption time is going to be over if you don't get up.",
  ui_story_5026_50260101_5_dialog_content = "Prize redemption time?",
  ui_story_5026_50260101_6_dialog_content = "The Shadow Prize Ticket in Umbraton you bought won the grand prize of ten million Nightium!",
  ui_story_5026_50260101_7_dialog_content = "<size=50>T-TEN MILLION?!</size>",
  ui_story_5026_50260101_8_dialog_content = "You're kidding... Am I dreaming?!",
  ui_story_5026_50260101_9_dialog_content = "Let's make careful plans for how we're going to use this money!",
  ui_story_5026_50260101_10_dialog_content = "Hm, let me think...",
  ui_story_5026_50260101_11_dialog_content = "First of all, I'm going to use three million of it to invest in the development of Cloud Gardens!",
  ui_story_5026_50260101_12_dialog_content = "It hasn't been long since the Obelisk of Return rose and changed the whole landscape of Eraveil.",
  ui_story_5026_50260101_13_dialog_content = "I was also busy with other things, and time passed... Cloud Gardens is still just beginning to shape up.",
  ui_story_5026_50260101_14_dialog_content = "Well, that's a reasonable request. I'll note it down.",
  ui_story_5026_50260101_15_dialog_content = "I also need another three million to find a reliable management team!",
  ui_story_5026_50260101_16_dialog_content = "You've done a really good job helping me take care of the Colossus, Vice.",
  ui_story_5026_50260101_17_dialog_content = "But Cloud Gardens is huge, so we need more manpower to handle it.",
  ui_story_5026_50260101_18_dialog_content = "I hope to recruit some extra hands to help me manage my home.",
  ui_story_5026_50260101_19_dialog_content = "Of course, of course.",
  ui_story_5026_50260101_20_dialog_content = "And finally, I want to set aside three million for Soroz's daily maintenance and repairs!",
  ui_story_5026_50260101_21_dialog_content = "Soroz has had it rough lately.",
  ui_story_5026_50260101_22_dialog_content = "Forced landings have become commonplace... It's sure been tough on Soroz.",
  ui_story_5026_50260101_23_dialog_content = "I hope Soroz won't be too mad when waking up...",
  ui_story_5026_50260101_24_dialog_content = "So, minus all of that, there's still one million left.",
  ui_story_5026_50260101_25_dialog_content = "Are you ready, PlayerName? We should get going.",
  ui_story_5026_50260101_26_dialog_content = "Oh no, it's so late already?",
  ui_story_5026_50260101_27_dialog_content = "So how are we going to spend the remaining million? Let's just think about it on our way there.",
  ui_story_5026_50260101_28_dialog_content = "Okay! Then...",
  ui_story_5026_50260101_29_dialog_content = "Let's go!",
  ui_story_5026_50260101_30_dialog_content = "Hmm? Where's Vice? Even Carleen is...",
  ui_story_5026_50260101_31_dialog_content = "Chubb!",
  ui_story_5026_50260101_32_dialog_content = "It was a dream...",
  ui_story_5026_50260101_33_dialog_content = "I was only planning on sitting down to take a breather, but I fell asleep.",
  ui_story_5026_50260101_34_dialog_content = "(Oh right, Carleen and Vice have respectively returned to Lumopolis and Gannon City to resume their duties.)",
  ui_story_5026_50260101_35_dialog_content = "(They're probably doing reports on their experiences as participants in the Obelisk of Return battle now.)",
  ui_story_5026_50260101_36_dialog_content = "(...)",
  ui_story_5026_50260101_37_dialog_content = "(A grand prize of ten million... Would be great if that were real...)",
  ui_story_5026_50260101_38_dialog_content = "(I'd better get some fresh air and clear my head.)",
  ui_story_5026_50260101_39_dialog_content = "It's so quiet.",
  ui_story_5026_50260101_40_dialog_content = "Only ruins are left now, but this place probably used to be really lively.",
  ui_story_5026_50260101_42_dialog_content = "Until—",
  ui_story_5026_50260101_43_dialog_content = "Chubb! Chubb!",
  ui_story_5026_50260101_44_dialog_content = "Huh? Did I zone out again? At this rate, I'll never get to the fishing place even if I walk all day.",
  ui_story_5026_50260101_46_dialog_content = "I wonder what Vice, Carleen, and everyone else are doing right now?",
  ui_story_5026_50260101_47_dialog_content = "Thanks to everyone's company, I never felt lonely in all the time that Soroz was unconscious.",
  ui_story_5026_50260101_48_dialog_content = "But they've all gone home now.",
  ui_story_5026_50260101_49_dialog_content = "And the place I should return to is here, Eraveil.",
  ui_story_5026_50260101_50_dialog_content = "This is how it should be, but why... Huh?",
  ui_story_5026_50260101_51_dialog_content = "Looks like there's something in the grass over there...",
  ui_story_5026_50260101_52_dialog_content = "Waaaaah?!",
  ui_story_5026_50260101_53_dialog_content = "G-Gaah?!",
  ui_story_5026_50260101_54_dialog_content = "H-How did an Eclipsite get into Cloud Gardens?",
  ui_story_5026_50260101_55_dialog_content = "Graaaaaah!",
  ui_story_5026_50260101_56_dialog_content = "... It doesn't seem very powerful.",
  ui_story_5026_50260101_57_dialog_content = "<size=33>Gah...</size>",
  ui_story_5026_50260101_58_dialog_content = "It doesn't seem very powerful, but I can't exactly deal with it with just a fishing rod...",
  ui_story_5026_50260101_59_dialog_content = "Ah! Don't run away!",
  ui_story_5026_50260101_60_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5026_50260101_61_dialog_content = "Fufufu!",
  ui_story_5026_50260101_62_dialog_content = "Looks like I came just in time.",
  ui_story_5026_50260101_63_dialog_content = "Bethel! Thanks for that!",
  ui_story_5026_50260101_64_dialog_content = "Easy peasy. I was more worried that my sudden visit would cause you trouble, PlayerName.",
  ui_story_5026_50260101_65_dialog_content = "Not at all! Without you, this patch of grass might have been destroyed by Spikepests.",
  ui_story_5026_50260101_66_dialog_content = "These guys run really fast... Oh, did you come here to see me for something?",
  ui_story_5026_50260101_67_dialog_content = "I actually came here today on behalf of Ms. Sheol.",
  ui_story_5026_50260101_68_dialog_content = "On behalf of Sheol?",
  ui_story_5026_50260101_69_dialog_content = "It's regarding a <color=#FFB400>bill</color> that hasn't been settled.",
  ui_story_5026_50260101_70_dialog_content = "PlayerName, do you remember your underground adventure in the Undercity near Eternal Night?",
  ui_story_5026_50260101_71_dialog_content = "If you're willing to do something for me in return, I'll be happy to gather intel on the Undercity for you.",
  ui_story_5026_50260101_72_dialog_content = "You better come back alive and pay up.",
  ui_story_5026_50260101_73_dialog_content = "Miss Vice doesn't seem to be around. She usually helps manage your expenses, doesn't she?",
  ui_story_5026_50260101_74_dialog_content = "Well then, here's the bill. Please have a look over it.",
  ui_story_5026_50260101_75_dialog_content = "Let's see... Huh?! <size=45>This is the price?!</size>",
  ui_story_5026_50260101_76_dialog_content = "I know. I'm still dreaming. That must be it! Ahahaha...",
  ui_story_5026_50260101_77_dialog_content = "Would you like to keep it on credit, PlayerName?",
  ui_story_5026_50260101_78_dialog_content = "I can negotiate on your behalf, but a record will be left with Miss Jane, the Umbraton Witness.",
  ui_story_5026_50260101_79_dialog_content = "This might affect your creditworthiness in Umbraton, as well as the long-term development of Cloud Gardens.",
  ui_story_5026_50260101_80_dialog_content = "I'll pay! I'll definitely pay! I just can't right now.",
  ui_story_5026_50260101_81_dialog_content = "Please allow me to ask one more question. How do you plan on getting your hands on this sum of money?",
  ui_story_5026_50260101_82_option_content = "Set up a stall in Umbraton and sell my psychic abilities?",
  ui_story_5026_50260101_83_option_content = "Catch some Corrupted Eclipsites?",
  ui_story_5026_50260101_84_dialog_content = "A sloppy business plan like that would never be approved, PlayerName.",
  ui_story_5026_50260101_85_dialog_content = "Let me think... Cloud Gardens is a pretty nice place.",
  ui_story_5026_50260101_86_dialog_content = "The scenery is beautiful, there are plenty of resources, and you can find lots of unique Caelestite creations.",
  ui_story_5026_50260101_87_dialog_content = "Chubb?",
  ui_story_5026_50260101_88_dialog_content = "A-Are you asking me to sell Cloud Gardens? Or sell Chubbs?",
  ui_story_5026_50260101_89_dialog_content = "Other Umbraton merchants would probably propose something similar.",
  ui_story_5026_50260101_90_dialog_content = "But this home of yours didn't come by easily, did it?",
  ui_story_5026_50260101_91_dialog_content = "What I mean is, if you spent more effort fixing it up, it could turn out a considerable profit.",
  ui_story_5026_50260101_92_dialog_content = "I'm ashamed to admit it, but so much happened lately that I've barely had the time to sort out my thoughts.",
  ui_story_5026_50260101_93_dialog_content = "So I haven't been able to manage my new home as well as I would've liked.",
  ui_story_5026_50260101_94_dialog_content = "And as you just saw, even Eclipsites are showing up here.",
  ui_story_5026_50260101_95_dialog_content = "Right when everyone happens to be gone!",
  ui_story_5026_50260101_97_dialog_content = "Please tell Sheol that I'm grateful for her help, and I won't forget the payment I owe her.",
  ui_story_5026_50260101_98_dialog_content = "I understand. I will apply for a grace period for you, PlayerName.",
  ui_story_5026_50260101_99_dialog_content = "Do you have a plan for dealing with those Eclipsites?",
  ui_story_5026_50260101_100_dialog_content = "Who knows where they even crawled out from...",
  ui_story_5026_50260101_100X1_dialog_content = "I thought the Chord of the Law had purged Eraveil of all Eclipsites.",
  ui_story_5026_50260101_100X2_dialog_content = "But it's been a while since things went down at the Obelisk of Return, so maybe these Eclipsites wandered over from other places.",
  ui_story_5026_50260101_100X3_dialog_content = "Well, if it's just a few Spikepests, even I should be able to...",
  ui_story_5026_50260101_101_dialog_content = "How about...",
  ui_story_5026_50260101_102_dialog_content = "How about hiring a team of managers that meet your expectations to help out?",
  ui_story_5026_50260101_103_dialog_content = "It would solve your immediate Eclipsite problem and you'd be able to receive counsel on how to go about designing Cloud Gardens. Two for the price of one.",
  ui_story_5026_50260101_104_dialog_content = "Sounds good, but how would I go about finding suitable candidates?",
  ui_story_5026_50260101_105_dialog_content = "Regarding the recruitment process and required resources...",
  ui_story_5026_50260101_106_dialog_content = "I'm willing to help you with all that, PlayerName. Please trust me.",
  ui_story_5026_50260101_107_dialog_content = "Don't worry. I'm helping out as a friend, so it's not a guild order.",
  ui_story_5026_50260101_108_dialog_content = "Thank you for being such a reliable friend, Bethel...",
  ui_story_5026_50260101_109_dialog_content = "I'll leave it to you then!",
  ui_story_5026_50260201_1_dialog_content = "<color=#e8d9bb>Outside Eraveil</color>",
  ui_story_5026_50260201_2_dialog_content = "Good. We should be nearing Cloud Gardens.",
  ui_story_5026_50260201_3_dialog_content = "Eraveil, in its own isolated corner of the world... Even Father wouldn't have any influence here.",
  ui_story_5026_50260201_4_dialog_content = "Keep up, <color=#FFB400>Sanae</color>.",
  ui_story_5026_50260201_5_dialog_content = "M-Miss Nina! Wait for me!",
  ui_story_5026_50260201_6_dialog_content = "Didn't I tell you to call me <color=#FFB400>Nina</color> before we left? You have to call me Nina when we're outside!",
  ui_story_5026_50260201_7_dialog_content = "You promised when we left Umbraton that we wouldn't be followed, right, Mr. Odd Jobs?",
  ui_story_5026_50260201_8_dialog_content = "You wound me with those words, Miss Andersen. I depend on the trust of clients for my livelihood.",
  ui_story_5026_50260201_9_dialog_content = "Odd Jobs will do anything, from saving the world to looking for cats, as long as the client asks...",
  ui_story_5026_50260201_10_dialog_content = "Well, let me ask you this then. What is he doing here?",
  ui_story_5026_50260201_11_dialog_content = "Argh. This is why I didn't want this job...",
  ui_story_5026_50260201_12_dialog_content = "Good day, Miss Nina. You've had a long journey, so please rest here.",
  ui_story_5026_50260201_13_dialog_content = "... <color=#FFB400>Minos</color>, when did you get here?",
  ui_story_5026_50260201_14_dialog_content = "I beg you, Miss, to not accuse Mr. Taki unfairly. I truly did not follow your group.",
  ui_story_5026_50260201_15_dialog_content = "Oho! A tent, picnic blanket, sparkling water, sandwiches, scented candles, and even fresh flowers...",
  ui_story_5026_50260201_16_dialog_content = "You're very well-prepared. It looks like you had already come here even before the lady stepped through the door of my office.",
  ui_story_5026_50260201_17_dialog_content = "The Andersens' elite butler is really something.",
  ui_story_5026_50260201_18_dialog_content = "With enough intel, Miss Nina's itinerary is not that difficult to predict.",
  ui_story_5026_50260201_19_dialog_content = "Please come back with me after you finish your tea, Miss. The Master is worried about you.",
  ui_story_5026_50260201_20_dialog_content = "I'm not going back! I-I'm on the run away from home, you know!",
  ui_story_5026_50260201_21_dialog_content = "Indeed, and I have my orders. Even if I have to chase you to the edge of the world...",
  ui_story_5026_50260201_22_dialog_content = "I must bring you home.",
  ui_story_5026_50260201_23_dialog_content = "Dummy! Father is a dummy!",
  ui_story_5026_50260201_24_dialog_content = "Please mind your language, Miss. Always maintain the elegance of a lady.",
  ui_story_5026_50260201_25_dialog_content = "Ahem. It looks like there's nothing more for me to do here. Thank you for your patronage, Miss Andersen.",
  ui_story_5026_50260201_26_dialog_content = "Remember to leave a good review when you return to Umbraton!",
  ui_story_5026_50260201_27_dialog_content = "I said, I'm not going back!",
  ui_story_5026_50260201_28_dialog_content = "At least not until I get closer to that Caelestite, realize my plans, and prove myself! Definitely not until then!",
  ui_story_5026_50260201_29_dialog_content = "U-Um, Mr. Minos, I...",
  ui_story_5026_50260201_30_dialog_content = "There is no need to explain yourself, Sanae. The priority now is to calm down our young miss and return home safely.",
  ui_story_5026_50260201_31_dialog_content = "You have lapsed in your duty as a maid of the Andersen family to make timely reports. I will take note of this in the end-of-month appraisal.",
  ui_story_5026_50260201_32_dialog_content = "W-Will I lose my job...?",
  ui_story_5026_50260201_33_dialog_content = "You're threatening her!",
  ui_story_5026_50260201_34_dialog_content = "Waah! Manae, stop it!",
  ui_story_5026_50260201_35_dialog_content = "What? I'm just speaking facts!",
  ui_story_5026_50260201_36_dialog_content = "I know that as the only person of the same age as her in the mansion, the young miss is very close to you.",
  ui_story_5026_50260201_37_dialog_content = "That's probably the reason why she thought it was necessary to bring you along on her escapade.",
  ui_story_5026_50260201_38_dialog_content = "However, your continued employment in the mansion depends on your performance this time.",
  ui_story_5026_50260201_39_dialog_content = "W-What do you mean...",
  ui_story_5026_50260201_40_dialog_content = "Sanae! Why are you taking so long? We're going to be late for the interview!",
  ui_story_5026_50260201_41_dialog_content = "C-Coming!",
  ui_story_5026_50260201_42_dialog_content = "The young miss's determination is very impressive.",
  ui_story_5026_50260201_43_dialog_content = "Then I, too, will have to take some drastic measures.",
  ui_story_5026_50260201_44_dialog_content = "<color=#e8d9bb>Cloud Gardens: Manager Interview Area</color>",
  ui_story_5026_50260201_45_dialog_content = "...",
  ui_story_5026_50260201_46_dialog_content = "<size=33>Come on. Say something, PlayerName.</size>",
  ui_story_5026_50260201_47_dialog_content = "<size=33>Just like we practiced!</size>",
  ui_story_5026_50260201_48_dialog_content = "R-Right... First question: What made you apply to be a manager of Cloud Gardens?",
  ui_story_5026_50260201_49_dialog_content = "That's so boring.",
  ui_story_5026_50260201_50_dialog_content = "What?",
  ui_story_5026_50260201_51_dialog_content = "I've changed my mind. Stop the interview. I just wanted to have a look around anyway.",
  ui_story_5026_50260201_52_dialog_content = "Come look for me again if you need something to be set on fire.",
  ui_story_5026_50260201_53_dialog_content = "I hope you find a suitable candidate soon.",
  ui_story_5026_50260201_54_dialog_content = "She's gone...",
  ui_story_5026_50260201_55_dialog_content = "You don't have to be so careful, PlayerName. Show some gravitas as an interviewer.",
  ui_story_5026_50260201_56_dialog_content = "You rule all of Eraveil!",
  ui_story_5026_50260201_57_dialog_content = "Next candidate, please!",
  ui_story_5026_50260201_58_dialog_content = "Hello, PlayerName. I-I'm Connolly.",
  ui_story_5026_50260201_59_dialog_content = "(Gravitas... I'm a ruler...)",
  ui_story_5026_50260201_60_option_content = "Copy Schwartz's steadiness",
  ui_story_5026_50260201_61_dialog_content = "Please have a seat, Miss Connolly. It's my pleasure to have you here.",
  ui_story_5026_50260201_62_dialog_content = "I'll get right to the point. Please explain your understanding of Cloud Gardens and of the manager position.",
  ui_story_5026_50260201_63_dialog_content = "Do you have strategies to deal with the Eclipsites? You're young, but do you have any suggestions? I'm all ears.",
  ui_story_5026_50260201_64_option_content = "Copy Reinhardt's boldness",
  ui_story_5026_50260201_65_dialog_content = "Hahaha! Come, Connolly!",
  ui_story_5026_50260201_66_dialog_content = "If I'm correct, you don't have any real-world experience as a manager, right?",
  ui_story_5026_50260201_67_dialog_content = "Perfect. I appreciate those with a fighting spirit.",
  ui_story_5026_50260201_68_dialog_content = "As long as you're willing to work hard, this won't be a problem. I'll make you an excellent \"soldier\"!",
  ui_story_5026_50260201_69_option_content = "Copy Bethlehem's cool",
  ui_story_5026_50260201_70_dialog_content = "Have a seat. It was the hand of fate that brought your arrival upon us.",
  ui_story_5026_50260201_71_dialog_content = "You look a little nervous. Would you like a cup of black tea?",
  ui_story_5026_50260201_72_dialog_content = "Uh... Mr. Navigator is acting very strangely today!",
  ui_story_5026_50260201_73_dialog_content = "I'm sorry! I wasn't trying to be difficult!",
  ui_story_5026_50260201_74_dialog_content = "Alas. I messed up again.",
  ui_story_5026_50260201_75_dialog_content = "It's getting late. How many more candidates are left?",
  ui_story_5026_50260201_76_dialog_content = "Here are the remaining resumes. Let me see...",
  ui_story_5026_50260201_77_dialog_content = "G-Graah!",
  ui_story_5026_50260201_78_dialog_content = "Is that a candidate? Looks quite unusual.",
  ui_story_5026_50260201_79_dialog_content = "(Eclipsian) I will do anything! Please just give me the job!",
  ui_story_5026_50260201_80_dialog_content = "How did an Eclipsite make its way in?!",
  ui_story_5026_50260201_81_dialog_content = "And there's more than one!",
  ui_story_5026_50260202_1_dialog_content = "I didn't expect Eclipsites to fumble their way into the recruitment area...",
  ui_story_5026_50260202_2_dialog_content = "The Eclipsite problem in Cloud Gardens is more serious than I thought.",
  ui_story_5026_50260202_3_dialog_content = "Though I'm in urgent need of a helper, I think we're done with interviews for the day.",
  ui_story_5026_50260202_4_dialog_content = "I'm so sorry... I did promise that I would provide help to you.",
  ui_story_5026_50260202_5_dialog_content = "No, no, it all comes down to me.",
  ui_story_5026_50260202_6_dialog_content = "I need to hire someone, but the salary I can offer isn't even enough to buy a replica painting.",
  ui_story_5026_50260202_7_dialog_content = "Although I have many friends in Umbraton...",
  ui_story_5026_50260202_8_dialog_content = "I can't keep relying on their goodwill. They should be paid for their hard work.",
  ui_story_5026_50260202_9_dialog_content = "But if things keep going on like this...",
  ui_story_5026_50260202_10_dialog_content = "I believe this is our first time meeting, Mr. Navigator.",
  ui_story_5026_50260202_11_dialog_content = "Wow, so this is the rumored Cloud Gardens...",
  ui_story_5026_50260202_12_dialog_content = "It's quite different from what the Umbraton Daily described in the serial: \"Revealed! The Enigmatic Last Caelestite!\"",
  ui_story_5026_50260202_13_dialog_content = "There are more candidates...?",
  ui_story_5026_50260202_14_dialog_content = "H-Hello. Let me have a look at your resume... You must be Nina.",
  ui_story_5026_50260202_15_dialog_content = "A graduate of Dawn Academy with extensive experience in business development and human resource management...",
  ui_story_5026_50260202_16_dialog_content = "That's right!",
  ui_story_5026_50260202_17_dialog_content = "And your companion Sanae can take care of house cleaning, gardening, and various laundering work?",
  ui_story_5026_50260202_18_dialog_content = "I-I'll do my best!",
  ui_story_5026_50260202_19_dialog_content = "They look like the best candidates so far!",
  ui_story_5026_50260202_20_dialog_content = "Excellent, PlayerName.",
  ui_story_5026_50260202_21_dialog_content = "Are you ready to reach your life's peak with my help?",
  ui_story_5026_50260202_22_dialog_content = "Huh?",
  ui_story_5026_50260202_23_dialog_content = "I will tailor-make a world domination plan for the last Caelestite on the continent!",
  ui_story_5026_50260202_24_dialog_content = "Domination?! That's a little dramatic...",
  ui_story_5026_50260202_25_dialog_content = "It would be a win-win situation for both of us. I believe you will make the right choice.",
  ui_story_5026_50260202_26_dialog_content = "O-Okay. Please give me a minute.",
  ui_story_5026_50260202_27_dialog_content = "The resume only lists the information of two people, so who might you be?",
  ui_story_5026_50260202_28_dialog_content = "Greetings. Please forgive my intrusion. You can call me Minos.",
  ui_story_5026_50260202_29_dialog_content = "I was trained at the Butler Training School in Lumopolis. Here are my certificate and license.",
  ui_story_5026_50260202_30_dialog_content = "Wow, very professional! Are the three of you a team?",
  ui_story_5026_50260202_31_dialog_content = "Of course not!",
  ui_story_5026_50260202_32_dialog_content = "What?",
  ui_story_5026_50260202_33_dialog_content = "Miss Nina and I have a minor misunderstanding. Please don't mind. I will take care of it.",
  ui_story_5026_50260202_34_dialog_content = "If I'm not mistaken, you must be quite satisfied with our resumes, correct?",
  ui_story_5026_50260202_35_dialog_content = "Yes...",
  ui_story_5026_50260202_36_dialog_content = "I'm honored to have been selected where all others have failed.",
  ui_story_5026_50260202_37_dialog_content = "Well, about that... Actually...",
  ui_story_5026_50260202_38_dialog_content = "You must have very strict requirements for your manager. The final selection is troubling you.",
  ui_story_5026_50260202_39_dialog_content = "Requirements aside, it's more the fact that the best salary I can offer you is quite...",
  ui_story_5026_50260202_40_dialog_content = "I have a proposal.",
  ui_story_5026_50260202_41_dialog_content = "How about the two ladies and myself <color=#FFB400>split into two groups</color> and serve you as <color=#FFB400>probationary managers</color> without pay?",
  ui_story_5026_50260202_42_dialog_content = "For free?",
  ui_story_5026_50260202_43_dialog_content = "That's correct. We will simultaneously act as your managers, and in the end, you will hire the most competent group.",
  ui_story_5026_50260202_44_dialog_content = "Your satisfaction comes first. Pay can be negotiated after the probation period.",
  ui_story_5026_50260202_45_dialog_content = "This is a common method for commercial bidding in Umbraton, I hope it can address your concerns.",
  ui_story_5026_50260202_46_dialog_content = "For free!",
  ui_story_5026_50260202_47_dialog_content = "Miss Nina, Sanae, I apologize for taking the liberty of putting forth this proposal. If there are any objections—",
  ui_story_5026_50260202_48_dialog_content = "Fine, let's compete!",
  ui_story_5026_50260202_49_dialog_content = "I don't care about pay, for the potential of Eraveil is not something that can be defined monetarily. Don't you think so?",
  ui_story_5026_50260202_50_dialog_content = "Uh, I guess so.",
  ui_story_5026_50260202_51_dialog_content = "In any case, getting three very capable helpers for free is more than I could ever have hoped for.",
  ui_story_5026_50260202_52_dialog_content = "Bethel, what is your opinion?",
  ui_story_5026_50260202_53_dialog_content = "...",
  ui_story_5026_50260202_54_dialog_content = "Great! Looks like we can wrap up the interviews then!",
  ui_story_5026_50260202_55_dialog_content = "Huh? Right!",
  ui_story_5026_50260202_56_dialog_content = "Well then, Minos, Nina, and Sanae... I'll be counting on you to manage Cloud Gardens!",
  ui_story_5026_50260202_57_dialog_content = "It's a bit belated, but... Welcome to Cloud Gardens. I hope you'll like it here!",
  ui_story_5026_50260202_58_dialog_content = "Nina, Nina Andersen...",
  ui_story_5026_50260202_59_dialog_content = "The young miss of the Andersen family. Why is she hiding her last name and applying for the manager position at Cloud Gardens?",
  ui_story_5026_50260202_60_dialog_content = "And Sanae is a maid whom I introduced to the Andersen family recently.",
  ui_story_5026_50260202_61_dialog_content = "As for Minos, he's a real butler.",
  ui_story_5026_50260202_62_dialog_content = "He was always following Count Andersen around like a shadow whenever I visited their mansion on business.",
  ui_story_5026_50260202_63_dialog_content = "What a strange group.",
  ui_story_5026_50260202_64_dialog_content = "But the Andersen family are friends with my father. I also heard that Nina was an earnest child when she was at Dawn Academy...",
  ui_story_5026_50260202_65_dialog_content = "Anywhow, there's still work to be done, so I have to return to Umbraton.",
  ui_story_5026_50260202_66_dialog_content = "There shouldn't be anything to worry about...",
  ui_story_5026_50260301_1_dialog_content = "<color=#e8d9bb>Cloud Gardens: Fountain of Hope</color>",
  ui_story_5026_50260301_2_dialog_content = "It was a recruitment notice published by the Cloudrover Guild that brought me here, but I didn't expect Bethel to have been the one behind it.",
  ui_story_5026_50260301_3_dialog_content = "She's already established a business relationship with the Caelestite? No less from a top student.",
  ui_story_5026_50260301_4_dialog_content = "And Minos, what the hell are you scheming?",
  ui_story_5026_50260301_5_dialog_content = "Please mind your language, Miss. Always maintain the elegance of a lady.",
  ui_story_5026_50260301_6_dialog_content = "It was simply a proposal, as I described to you and PlayerName.",
  ui_story_5026_50260301_7_dialog_content = "Just to stop me from staying here? Do you think I'll go home obediently that way?",
  ui_story_5026_50260301_8_dialog_content = "I would've thought that someone Father trusts so much would've come up with something more clever.",
  ui_story_5026_50260301_9_dialog_content = "You give me too much credit, Miss. It is my honor to receive the Master's and your acknowledgement.",
  ui_story_5026_50260301_10_dialog_content = "I was not praising you!",
  ui_story_5026_50260301_11_dialog_content = "Let me be clear—I won't lose!",
  ui_story_5026_50260301_12_dialog_content = "I have so many stores in Umbraton: clothing stores, jewelry stores, weapon stores...",
  ui_story_5026_50260301_13_dialog_content = "A mere country estate is nothing for me.",
  ui_story_5026_50260301_14_dialog_content = "Managing a place like this is as easy as pie.",
  ui_story_5026_50260301_15_dialog_content = "Anyway, after I gain the trust of the Caelestite...",
  ui_story_5026_50260301_16_dialog_content = "I will turn this place into a commercial metropolis that is not inferior to Umbraton in any way, step by step!",
  ui_story_5026_50260301_17_dialog_content = "One day, this place will go farther than that dead city breathing in the shadow of Lumopolis.",
  ui_story_5026_50260301_18_dialog_content = "I'll let you and Father know that even without the wealth and influence of the Andersen family...",
  ui_story_5026_50260301_19_dialog_content = "I can still make something of myself!",
  ui_story_5026_50260301_20_dialog_content = "Of course, Miss. Your grand vision is admirable.",
  ui_story_5026_50260301_21_dialog_content = "Please allow me to make one more proposal then.",
  ui_story_5026_50260301_22_dialog_content = "If you can beat me in <color=#FFB400>any one thing</color> when working in Cloud Gardens, I will give up on bringing you home.",
  ui_story_5026_50260301_23_dialog_content = "Keep going.",
  ui_story_5026_50260301_24_dialog_content = "If you do win, I will leave immediately. We will not see each other again unless you wish it.",
  ui_story_5026_50260301_25_dialog_content = "You promise?",
  ui_story_5026_50260301_26_dialog_content = "I promise. Besides, you can get some helpers. I recommend it.",
  ui_story_5026_50260301_27_dialog_content = "But it's difficult to say how much help Sanae will be to you. After all, she broke more teacups than she washed in the mansion.",
  ui_story_5026_50260301_28_dialog_content = "You...!",
  ui_story_5026_50260301_29_dialog_content = "M-Miss! I mean, Nina! PlayerName is here.",
  ui_story_5026_50260301_30_dialog_content = "Sorry for being late. It took me some time to clean up the interview area.",
  ui_story_5026_50260301_31_dialog_content = "Did something happen?",
  ui_story_5026_50260301_32_dialog_content = "(I thought I saw Nina trying to hit Minos on the head with her umbrella... That's an umbrella, right?)",
  ui_story_5026_50260301_33_dialog_content = "Nothing at all!",
  ui_story_5026_50260301_34_dialog_content = "There is no need to worry about it, Mr. Navigator. Please go ahead.",
  ui_story_5026_50260301_35_dialog_content = "Ahem, so, like I wrote in the job description...",
  ui_story_5026_50260301_36_dialog_content = "I hope that you will join me in patrolling the entire area, assessing the severity of the Eclipsite invasion, and eliminating Eclipsites.",
  ui_story_5026_50260301_37_dialog_content = "In addition, I would like you to experience the daily tasks of Cloud Gardens and make suggestions on how to generate income as professionals.",
  ui_story_5026_50260301_38_dialog_content = "(Bethel wrote the description for me, and the wording is so formal! I'm not quite used to it...)",
  ui_story_5026_50260301_39_dialog_content = "T-Then... I'll give you a brief introduction before we start working.",
  ui_story_5026_50260301_40_dialog_content = "This is the central area of Cloud Gardens.",
  ui_story_5026_50260301_41_dialog_content = "No matter where you want to visit, this is the most convenient starting place.",
  ui_story_5026_50260301_42_dialog_content = "The white tower behind us is called the Hyacinth Tower.",
  ui_story_5026_50260301_43_dialog_content = "All of these white towers, including the Hyacinth Tower, are complexes left behind by ancient Caelestites.",
  ui_story_5026_50260301_44_dialog_content = "There are also many blueprints piled up in the towers, as well as some devices I failed to activate...",
  ui_story_5026_50260301_45_dialog_content = "Oh? Inventions by Caelestites perhaps? Do you have weapon blueprints?",
  ui_story_5026_50260301_46_dialog_content = "Uh... I've only discovered blueprints for buildings and furniture so far.",
  ui_story_5026_50260301_47_dialog_content = "PlayerName, you are the only known Caelestite so far.",
  ui_story_5026_50260301_48_dialog_content = "You own a giant airship and mysterious ancient technology, plus you can enhance Aurorians for battle.",
  ui_story_5026_50260301_49_dialog_content = "They say that Caelestites were always kind and peaceful...",
  ui_story_5026_50260301_50_dialog_content = "But your dream does not stop at redeveloping Eraveil, does it?",
  ui_story_5026_50260301_51_dialog_content = "(Nina seems to have done some research on me!)",
  ui_story_5026_50260301_52_dialog_content = "You seem surprised.",
  ui_story_5026_50260301_53_dialog_content = "You're an important business partner, so a background check was essential.",
  ui_story_5026_50260301_54_dialog_content = "With that said, are you interested in my world domination plan now?",
  ui_story_5026_50260301_55_dialog_content = "Well, so far I really haven't even gotten things settled in Eraveil yet...",
  ui_story_5026_50260301_56_dialog_content = "The priority now is focusing on the tasks in front of us.",
  ui_story_5026_50260301_57_dialog_content = "If there are no other questions...",
  ui_story_5026_50260301_58_dialog_content = "Why don't we begin with planting trees?",
  ui_story_5026_50260301_59_dialog_content = "So this is where you cultivate Unique Trees...",
  ui_story_5026_50260301_60_dialog_content = "...Or well, anything.",
  ui_story_5026_50260301_61_dialog_content = "Perhaps their unique quality is that they can turn invisible?",
  ui_story_5026_50260301_62_dialog_content = "The isolated Eraveil does indeed have very unique plant species.",
  ui_story_5026_50260301_63_dialog_content = "I have to admit that I've never cultivated plants before. So, as you can see...",
  ui_story_5026_50260301_64_dialog_content = "Most of what was planted didn't germinate, and the ones that did grow turned out crooked?",
  ui_story_5026_50260301_65_dialog_content = "Ah, yes. But I don't intend on giving up.",
  ui_story_5026_50260301_66_dialog_content = "Let's trim them and plant new seeds.",
  ui_story_5026_50260301_67_dialog_content = "Sounds like a job that would make skirts dirty...",
  ui_story_5026_50260301_68_dialog_content = "What's this thing that looks like a giant spoon?",
  ui_story_5026_50260301_69_dialog_content = "It's a shovel, for shoveling dirt. Have you never seen one before?",
  ui_story_5026_50260301_70_dialog_content = "Of course I have! I've seen it many times on my visits to the farm with my father!",
  ui_story_5026_50260301_71_dialog_content = "This one just looks different from the ones used by my family!",
  ui_story_5026_50260301_72_dialog_content = "Just... Just hand it to me, and let me have a good look at it!",
  ui_story_5026_50260301_73_dialog_content = "Are there so many types of shovels? Planting things is much more complicated than I thought.",
  ui_story_5026_50260301_74_dialog_content = "Let me go see what the other two are up to.",
  ui_story_5026_50260301_75_dialog_content = "Hello, PlayerName.",
  ui_story_5026_50260301_76_dialog_content = "About the pruning of the Unique Tree... would you prefer the style of Lumopolis, or that of the Northland Winter Palace?",
  ui_story_5026_50260301_77_dialog_content = "Both are popular in Umbraton, but our Last Caelestite might have different tastes.",
  ui_story_5026_50260301_78_dialog_content = "Please forgive me. I got ahead of myself.",
  ui_story_5026_50260301_79_dialog_content = "... This is so extra!",
  ui_story_5026_50260301_80_dialog_content = "<size=37>I wonder how fruit from a Unique Tree would taste like?</size>",
  ui_story_5026_50260301_81_dialog_content = "<size=35>Would I gain any special powers from eating it? Would I grow wings and a tail?</size>",
  ui_story_5026_50260301_82_dialog_content = "<size=33>This is the garden of that Enigmatic Last Caelestite after all...</size>",
  ui_story_5026_50260301_83_dialog_content = "<size=40>Aah! This is not the time for pondering these things! If I don't help Mr. Minos, I'll...</size>",
  ui_story_5026_50260301_84_dialog_content = "<size=33>But I don't want to do something that will make Miss Nina sad either...</size>",
  ui_story_5026_50260301_85_dialog_content = "(Sanae appears to be staring at the pit in front of her and mumbling to herself...)",
  ui_story_5026_50260301_86_dialog_content = "Um, Sanae...",
  ui_story_5026_50260301_87_dialog_content = "Yes! That's me!",
  ui_story_5026_50260301_88_dialog_content = "We just need some shallow holes for burying the seeds. The hole you dug is deep enough to bury me in.",
  ui_story_5026_50260301_89_dialog_content = "I-I just did some light digging!",
  ui_story_5026_50260301_90_dialog_content = "Chubb...",
  ui_story_5026_50260301_91_dialog_content = "Caelestite detected, Chubb!",
  ui_story_5026_50260301_92_dialog_content = "What's that sound?",
  ui_story_5026_50260301_93_dialog_content = "This thick shovel is really impressive, PlayerName.",
  ui_story_5026_50260301_94_dialog_content = "We just buried the tree seeds and pat the dirt with the shovel twice...",
  ui_story_5026_50260301_95_dialog_content = "And here we have a talking Unique Tree before us in the blink of an eye.",
  ui_story_5026_50260301_96_dialog_content = "Oh, this isn't a Unique Tree. It probably just happened to walk onto this heap.",
  ui_story_5026_50260301_97_dialog_content = "I... I totally knew that was the case! How could it be a Unique Tree?",
  ui_story_5026_50260301_98_dialog_content = "We call them Chubbs. They appeared with Cloud Gardens after the Obelisk of Return rose up.",
  ui_story_5026_50260301_99_dialog_content = "Chubb!",
  ui_story_5026_50260301_100_dialog_content = "It's...",
  ui_story_5026_50260301_101_dialog_content = "It's so cute...!",
  ui_story_5026_50260301_102_dialog_content = "Ahem, I mean, what can this little one do?",
  ui_story_5026_50260301_103_dialog_content = "From what you've described, it's a resident of Cloud Gardens, like you.",
  ui_story_5026_50260301_104_dialog_content = "So other than being cute, it should contribute something to this place, right?",
  ui_story_5026_50260301_105_dialog_content = "Chubb...",
  ui_story_5026_50260301_106_dialog_content = "Some Chubbs teach me things about Cloud Gardens and help me take care of the Unique Trees.",
  ui_story_5026_50260301_107_dialog_content = "But most Chubbs just walk around or doze here.",
  ui_story_5026_50260301_108_dialog_content = "I don't know much about the specifics of their structure or function either.",
  ui_story_5026_50260301_109_dialog_content = "But just watching them walk around makes me happy.",
  ui_story_5026_50260301_110_dialog_content = "Well, a few of the Rediesel Wrench and Illumina guys like chasing after them, saying things about taking them apart to have a look...",
  ui_story_5026_50260301_111_dialog_content = "Chubb! No taking Chubb apart!",
  ui_story_5026_50260301_112_dialog_content = "It's timid, like a rabbit.",
  ui_story_5026_50260301_113_dialog_content = "Uh... I-I only pet this little fellow because it looks afraid. It's not like I wanted to pet it or anything. Don't get me wrong.",
  ui_story_5026_50260301_114_dialog_content = "(Eclipsites have appeared in Cloud Gardens, but these Chubbs are still relaxed.)",
  ui_story_5026_50260301_115_dialog_content = "(Is it because they're air-headed, or like the ancient Caelestites, they simply don't see Eclipsites as enemies?)",
  ui_story_5026_50260301_116_dialog_content = "(Relics from eons ago hold so many secrets, and I'm not sure I want to know them all...)",
  ui_story_5026_50260301_117_dialog_content = "Chubb?",
  ui_story_5026_50260301_118_dialog_content = "(It must be because they're air-headed.)",
  ui_story_5026_50260301_119_dialog_content = "Chubb!",
  ui_story_5026_50260301_120_dialog_content = "Another one? Do you want me to scratch your ear too? Well, I-I can't say no to that.",
  ui_story_5026_50260301_121_dialog_content = "So if this one is named Chubb, what about the other one?",
  ui_story_5026_50260301_122_dialog_content = "Huh? It's also named Chubb.",
  ui_story_5026_50260301_123_dialog_content = "But they look different. Look at the shape of their eyes, and the curve of their mouths when they smile!",
  ui_story_5026_50260301_124_dialog_content = "Uh, there's a difference?",
  ui_story_5026_50260301_125_dialog_content = "What an amateur...",
  ui_story_5026_50260301_126_dialog_content = "Amateur?",
  ui_story_5026_50260301_127_dialog_content = "Listen up, PlayerName.",
  ui_story_5026_50260301_128_dialog_content = "One of the main principles of management is to know your employees well.",
  ui_story_5026_50260301_129_dialog_content = "I've been meaning to ask you this since earlier... Where are your staff roster, your account books, and your estate logbook?",
  ui_story_5026_50260301_130_dialog_content = "What are all those?",
  ui_story_5026_50260301_131_dialog_content = "You don't even know what a staff roster is?",
  ui_story_5026_50260301_132_dialog_content = "I feel like I would be insulting your intelligence if I gave you an explanation, but I can start from the basics.",
  ui_story_5026_50260301_133_dialog_content = "Wait, I think I sense something close by... That's—",
  ui_story_5026_50260301_134_dialog_content = "Waaaaah!",
  ui_story_5026_50260301_135_dialog_content = "N-Now what?!",
  ui_story_5026_50260301_136_dialog_content = "<anim type=Shake>Graagh!</anim>",
  ui_story_5026_50260301_137_dialog_content = "I-I just poked the bushes a little...",
  ui_story_5026_50260301_138_dialog_content = "How exactly do you define \"a little\"?!",
  ui_story_5026_50260402_1_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_5026_50260402_2_dialog_content = "Hmph. Easy.",
  ui_story_5026_50260402_3_dialog_content = "Sanae, PlayerName, are you all right?",
  ui_story_5026_50260402_4_dialog_content = "Th-They just jumped out of the bushes suddenly and scared me.",
  ui_story_5026_50260402_5_dialog_content = "This is a surprise. Nina, you're actually skilled in combat.",
  ui_story_5026_50260402_6_dialog_content = "Hmph, at least you can tell.",
  ui_story_5026_50260402_7_dialog_content = "Your psychic ability is also very special, allowing you to see trails of light. It's given me new design inspiration.",
  ui_story_5026_50260402_8_dialog_content = "Wait a second... What did you mean by \"surprise\"? Are you underestimating me?",
  ui_story_5026_50260402_9_dialog_content = "Because you don't look like someone who spends a lot of time waving weapons around...",
  ui_story_5026_50260402_10_dialog_content = "But you're right. I'm sorry, I shouldn't have made assumptions about you based on first impressions.",
  ui_story_5026_50260402_11_dialog_content = "Thanks to you, we've gotten rid of the enemies and this area is now completely free of Darkflow.",
  ui_story_5026_50260402_12_dialog_content = "Thank you, Nina.",
  ui_story_5026_50260402_13_dialog_content = "Th-There's no need to be so formal, and...",
  ui_story_5026_50260402_14_dialog_content = "And no need to come so close either!",
  ui_story_5026_50260402_15_dialog_content = "(You're the one who got close!)",
  ui_story_5026_50260402_16_dialog_content = "<size=33>He's the one Uncle Istvan has been keeping a close watch on... I can't let my guard down.</size>",
  ui_story_5026_50260402_17_dialog_content = "And you're right. As a lady...",
  ui_story_5026_50260402_18_dialog_content = "... What do they say again? Oh, as a lady, I should be \"more elegant and dignified\" and should not \"prance around with weapons.\"",
  ui_story_5026_50260402_19_dialog_content = "Not to mention I'd rather craft weapons than wield them.",
  ui_story_5026_50260402_20_dialog_content = "Who knows what those judgmental noblewomen would say if they found out about this.",
  ui_story_5026_50260402_21_dialog_content = "Noblewomen?",
  ui_story_5026_50260402_22_dialog_content = "N-Nothing! Eliminating Eclipsites is part of my job, I was just being a good employee!",
  ui_story_5026_50260402_23_dialog_content = "Besides, this is only the first step in fixing Cloud Gardens up—just sit back and watch me work in all my glory!",
  ui_story_5026_50260402_24_dialog_content = "Oh, speaking of which.",
  ui_story_5026_50260402_25_dialog_content = "Minos seems to have finished all the planting work while we were chatting about Chubb differences.",
  ui_story_5026_50260402_26_dialog_content = "Huh?",
  ui_story_5026_50260402_27_dialog_content = "He loosened the soil, sowed the seeds, watered them, and fertilized them...",
  ui_story_5026_50260402_28_dialog_content = "He also placed marker signs for each plot of land, and surrounded them with flowers that complement the color of the trees.",
  ui_story_5026_50260402_29_dialog_content = "Chubb sees it too, Chubb!",
  ui_story_5026_50260402_30_dialog_content = "Amazing, Chubb!",
  ui_story_5026_50260402_31_dialog_content = "You flatter me, Mr. Navigator... and dear little Chubbs.",
  ui_story_5026_50260402_32_dialog_content = "Please allow me to remind you, Master of Cloud Gardens, that it is too soon to feel reassured about the Eclipsite problem.",
  ui_story_5026_50260402_33_dialog_content = "I just saw a dark shadow that I suspected to be an Eclipsite dashing into those buildings in the distance.",
  ui_story_5026_50260402_34_dialog_content = "I shall go ahead and investigate, just to be on the safe side. Please excuse me.",
  ui_story_5026_50260402_35_dialog_content = "Whoa, he left so quickly!",
  ui_story_5026_50260402_36_dialog_content = "I just lost a round. I can't fall behind again.",
  ui_story_5026_50260402_37_dialog_content = "Sanae, let's go!",
  ui_story_5026_50260402_38_dialog_content = "Do we really stand a chance against Mr. Minos...?",
  ui_story_5026_50260402_39_dialog_content = "It feels like they're more concerned for Cloud Gardens' safety than I am...",
  ui_story_5026_50260402_40_dialog_content = "Is this the contract dedication that Umbratons are known for?",
  ui_story_5026_50260501_1_dialog_content = "What is this? There's no Eclipsite anywhere!",
  ui_story_5026_50260501_2_dialog_content = "Did Minos deal with it already?",
  ui_story_5026_50260501_3_dialog_content = "I don't sense any Darkflow either. Still, we shouldn't let our guard down.",
  ui_story_5026_50260501_4_dialog_content = "This large clearing in front of us should be safe, at least.",
  ui_story_5026_50260501_5_dialog_content = "This place looks sort of familiar...",
  ui_story_5026_50260501_6_dialog_content = "Obviously. No matter which direction you look in here, it's just the same grassy field stretching outwards.",
  ui_story_5026_50260501_7_dialog_content = "Oh right! I went on a treasure hunt near here before, with Vice!",
  ui_story_5026_50260501_8_dialog_content = "I've heard that people in rural areas will use such methods to attract adventurers who dream of easy riches.",
  ui_story_5026_50260501_9_dialog_content = "It's not a bad way to stimulate the local economy, but...",
  ui_story_5026_50260501_10_dialog_content = "This just looks like an empty field. You can really find treasure here?",
  ui_story_5026_50260501_11_dialog_content = "Uh, well...",
  ui_story_5026_50260501_12_dialog_content = "<size=45>Waaah!</size>",
  ui_story_5026_50260501_13_dialog_content = "H-Huh?!",
  ui_story_5026_50260501_14_dialog_content = "What tripped me... a stone?",
  ui_story_5026_50260501_15_dialog_content = "Found treasure! Chubb!",
  ui_story_5026_50260501_16_dialog_content = "Waah, I'm so dizzy... The Chubb seems to have multiplied...",
  ui_story_5026_50260501_17_dialog_content = "There are really a lot of Chubbs, Chubb!",
  ui_story_5026_50260501_18_dialog_content = "Owie, owie, go away! Chubb!",
  ui_story_5026_50260501_19_dialog_content = "I'm squished, Chubb...",
  ui_story_5026_50260501_20_dialog_content = "Sanae always seems to get herself into situations. Should I consider that unlucky, or lucky...?",
  ui_story_5026_50260501_21_dialog_content = "Nina? What is it? Would you like to dig too?",
  ui_story_5026_50260501_22_dialog_content = "I don't really want to.",
  ui_story_5026_50260501_23_dialog_content = "My dress will get stained as there's so much dirt. This dress is my latest work...",
  ui_story_5026_50260501_24_dialog_content = "(She keeps staring at the tool in my hand...)",
  ui_story_5026_50260501_25_dialog_content = "You should give it a shot. Here, you can borrow this.",
  ui_story_5026_50260501_26_dialog_content = "Um... S-Since you insist, and this is a part daily Cloud Gardens duties, I'll give it a try.",
  ui_story_5026_50260501_27_dialog_content = "But you may need to move faster.",
  ui_story_5026_50260501_28_dialog_content = "Look there. Somehow, Minos already has a stash piled by his feet.",
  ui_story_5026_50260501_29_dialog_content = "Even the Chubbs look impressed.",
  ui_story_5026_50260501_30_dialog_content = "(Huh? Wait...)",
  ui_story_5026_50260501_31_dialog_content = "(Have these guys ever bounced around me with such eagerness and happiness before?)",
  ui_story_5026_50260501_32_dialog_content = "I knew it already, but he really is good at everything... It's so unfair!",
  ui_story_5026_50260501_33_dialog_content = "Yeah, I wonder how he did it? I was so focused on watching Sanae that I didn't pay attention to what he was doing...",
  ui_story_5026_50260501_34_dialog_content = "Hey, don't you have any better tools for treasure hunting?",
  ui_story_5026_50260501_35_dialog_content = "There are some other tools next to the windmill there.",
  ui_story_5026_50260501_36_dialog_content = "Wait, I think they're in the warehouse next to the windmill... but that place hasn't been cleaned for a long time.",
  ui_story_5026_50260501_37_dialog_content = "Tsk. This won't do.",
  ui_story_5026_50260501_38_dialog_content = "As the master of Cloud Gardens, you have to be know your estate like the back of your hand!",
  ui_story_5026_50260501_39_dialog_content = "Anyway, I'll go take a look myself.",
  ui_story_5026_50260501_40_dialog_content = "Ah, Nina! Wait for me!",
  ui_story_5026_50260501_41_dialog_content = "<color=#e8d9bb>Cloud Gardens: Tool Room</color>",
  ui_story_5026_50260501_42_dialog_content = "Ugh! It's so dusty in here!",
  ui_story_5026_50260501_43_dialog_content = "There's a lot of half-assembled furniture. Are these all masterpieces created by the Caelestite?",
  ui_story_5026_50260501_44_dialog_content = "I didn't peg PlayerName to be such a hard worker.",
  ui_story_5026_50260501_45_dialog_content = "Their scarcity would make them valuable. If they were sent to the auction house in Umbraton as Caelestite artworks, they'd probably fetch good prices.",
  ui_story_5026_50260501_46_dialog_content = "And they could be packaged nicely, even displayed in an exhibition...",
  ui_story_5026_50260501_47_dialog_content = "No. Now's not the time to think about those things.",
  ui_story_5026_50260501_48_dialog_content = "Tools... Where are the tools? It's too dark in here...",
  ui_story_5026_50260501_49_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5026_50260501_50_dialog_content = "<size=45>Huh? Ahh!</size>",
  ui_story_5026_50260501_51_dialog_content = "It was just the wind. I knew it...",
  ui_story_5026_50260501_52_dialog_content = "<color=#e8d9bb>Clang...</color>",
  ui_story_5026_50260501_53_dialog_content = "<size=45>Huh?!</size>",
  ui_story_5026_50260501_54_dialog_content = "It... It must be a Chubb hiding behind the furniture...",
  ui_story_5026_50260501_55_dialog_content = "D-Don't hide in the dark... Come out!",
  ui_story_5026_50260501_56_dialog_content = "I'm not afraid at all. Not one bit...",
  ui_story_5026_50260501_57_dialog_content = "<size=45>Aaaaah!</size>",
  ui_story_5026_50260501_58_dialog_content = "<anim type=Shake><size=50>Graaagh!</size></anim>",
  ui_story_5026_50260501_59_dialog_content = "Seriously? So it wasn't a ghost...",
  ui_story_5026_50260501_60_dialog_content = "How dare a mere Eclipsite frighten me!",
  ui_story_5026_50260502_1_dialog_content = "Are you okay, Nina?",
  ui_story_5026_50260502_2_dialog_content = "I thought I heard a scream earlier.",
  ui_story_5026_50260502_3_dialog_content = "Y-You heard wrong! T-This warehouse isn't dark, nor scary!",
  ui_story_5026_50260502_4_dialog_content = "It was just a few Eclipsites, but I dealt with them easy peasy!",
  ui_story_5026_50260502_5_dialog_content = "It's good that you're fine. Have you found the right tool?",
  ui_story_5026_50260502_6_dialog_content = "While you were busy looking for tools, Minos, he... he already turned the whole place inside out.",
  ui_story_5026_50260502_7_dialog_content = "What?!",
  ui_story_5026_50260502_8_dialog_content = "He's with the Chubbs right now, restoring the grass to the way it was. He watered it, and even counted the number of earthworms...",
  ui_story_5026_50260502_9_dialog_content = "I see. This is what it's actually like to have Minos as an opponent.",
  ui_story_5026_50260502_10_dialog_content = "Tricking me into eating more vegetables and stopping me from pulling pranks on the governess were just child's play.",
  ui_story_5026_50260502_11_dialog_content = "Have you and Minos known each other for a long time?",
  ui_story_5026_50260502_12_dialog_content = "Yes, a very long time. And I've tolerated him for a long time too.",
  ui_story_5026_50260502_13_dialog_content = "I've had enough of him and Father treating me like a child.",
  ui_story_5026_50260502_14_dialog_content = "Okay, let's go on to the next round of the test!",
  ui_story_5026_50260502_15_dialog_content = "The third time's the charm. I'm not going to lose to Minos again.",
  ui_story_5026_50260502_16_dialog_content = "Next, let's go look for ore.",
  ui_story_5026_50260502_17_dialog_content = "Huh... Does Cloud Gardens have special local ores?",
  ui_story_5026_50260502_18_dialog_content = "My fam—I mean my business partners, the Andersen family, handles half of Umbraton's minerals.",
  ui_story_5026_50260502_19_dialog_content = "If I can find a rare ore deposit here, I bet that would impress the family's head, right?",
  ui_story_5026_50260502_20_dialog_content = "Half the minerals? This Andersen family sounds really impressive.",
  ui_story_5026_50260502_21_dialog_content = "W-Who knows? I only have a business relationship with them!",
  ui_story_5026_50260502_22_dialog_content = "What I'm more concerned with is how minerals can be used, especially the gems.",
  ui_story_5026_50260502_23_dialog_content = "The process of selecting, appraising, sending them to be cut, setting—",
  ui_story_5026_50260502_24_dialog_content = "Then personally incorporating each gem as part of a weapon, piece of jewelry, or outfit.",
  ui_story_5026_50260502_25_dialog_content = "You can design so many things? You're incredible, Nina.",
  ui_story_5026_50260502_26_dialog_content = "Heheh, my works are very popular in Umbraton...",
  ui_story_5026_50260502_27_dialog_content = "...",
  ui_story_5026_50260502_28_dialog_content = "<size=33>... But I've recently learned that this popularity might not stem from my own skills.</size>",
  ui_story_5026_50260502_29_dialog_content = "How come?",
  ui_story_5026_50260502_30_dialog_content = "Nothing. I saw a lot of furniture pieces in the warehouse. Did you make those?",
  ui_story_5026_50260502_31_dialog_content = "Yeah. I'm just a beginner, but I've recently found pleasure in making furniture and constructing buildings.",
  ui_story_5026_50260502_32_dialog_content = "Oh? So you designed all the furniture and structures I've seen in Cloud Gardens?",
  ui_story_5026_50260502_33_dialog_content = "Ah... Well, I just found blueprints in various parts around the area of ancient Caelestite structures and restored the originals.",
  ui_story_5026_50260502_34_dialog_content = "What fun is there to be had from copying designs of the past?",
  ui_story_5026_50260502_35_dialog_content = "When you put it like that, I...",
  ui_story_5026_50260502_36_dialog_content = "I was out of line.",
  ui_story_5026_50260502_37_dialog_content = "Huh?",
  ui_story_5026_50260502_38_dialog_content = "You have your own reasons. I shouldn't criticize your feelings.",
  ui_story_5026_50260502_39_dialog_content = "No.",
  ui_story_5026_50260502_40_dialog_content = "Your question makes me think seriously for the first time about why restoring things makes me happy.",
  ui_story_5026_50260502_41_dialog_content = "Why?",
  ui_story_5026_50260502_42_dialog_content = "It feels like in this way, I'd be able to recreate some of the sceneries that have been lost to time and war...",
  ui_story_5026_50260502_43_dialog_content = "And it's almost as if that would chase away the loneliness.",
  ui_story_5026_50260502_44_dialog_content = "... You are not quite what I imagined, PlayerName.",
  ui_story_5026_50260502_45_dialog_content = "What do you mean?",
  ui_story_5026_50260502_46_dialog_content = "Sanae often talks to me about a certain column in the Umbraton Daily that claims to accurately detail the life of PlayerName the Caelestite.",
  ui_story_5026_50260502_47_dialog_content = "Father says that the paper prints more nonsense in its pages than the Nightmist Market's fakes.",
  ui_story_5026_50260502_48_dialog_content = "Someone actually writes a column about me?",
  ui_story_5026_50260502_49_dialog_content = "You're more popular than you think, you know.",
  ui_story_5026_50260502_50_dialog_content = "I remember the title of the first article. \"Shocking! A Teen Comes Back to Life After Being Buried for Seventeen Years!\"",
  ui_story_5026_50260502_51_dialog_content = "If you're interested, Sanae keeps clippings of each week's article without fail and puts them into a scrapbook...",
  ui_story_5026_50260502_52_dialog_content = "She also bought the book that's a publication of all the articles in one volume.",
  ui_story_5026_50260502_53_dialog_content = "... Please tell me how to get them to stop writing.",
  ui_story_5026_50260502_54_dialog_content = "Interesting. Are you trying to take control of the narrative?",
  ui_story_5026_50260502_55_dialog_content = "Indeed, as a new power that's only just emerging, it's important for you to manage your image as well.",
  ui_story_5026_50260502_56_dialog_content = "No, I just find it embarrassing...",
  ui_story_5026_50260502_57_dialog_content = "You are a glistening piece of meat for the tabloids. Better watch out and keep your secrets close.",
  ui_story_5026_50260502_58_dialog_content = "I'll be careful...",
  ui_story_5026_50260502_59_dialog_content = "Oh no! I didn't realize we've been chatting for so long!",
  ui_story_5026_50260502_60_dialog_content = "Sanae and Minos are probably still waiting. We'd better set off now to go to the ores!",
  ui_story_5026_50260502_61_dialog_content = "I hope we won't encounter any more Eclipsites on our way there.",
  ui_story_5026_50260702_1_dialog_content = "Where did all these Eclipsites come from in the first place?",
  ui_story_5026_50260702_2_dialog_content = "Is their presence really that surprising to you? It's the norm to be constantly bothered by Eclipsites here on this continent.",
  ui_story_5026_50260702_3_dialog_content = "I was living on the Colossus before this, so I never really experienced it...",
  ui_story_5026_50260702_4_dialog_content = "It goes without saying for the farms, forests, and ranches around Umbraton. Even the fishermen along the Gold River know this.",
  ui_story_5026_50260702_5_dialog_content = "Times of peace are scarce and precious.",
  ui_story_5026_50260702_6_dialog_content = "You can neither fly in the sky nor hide underground here, and it's not under any powerful Aurorian's protection either.",
  ui_story_5026_50260702_7_dialog_content = "So on the contrary, I don't see how Cloud Gardens could possibly be exempt from Eclipsite intrusions.",
  ui_story_5026_50260702_8_dialog_content = "Unless Caelestites and Aurorians are decisively different in how we deal with Eclipsites?",
  ui_story_5026_50260702_9_dialog_content = "(What an acute question!)",
  ui_story_5026_50260702_10_dialog_content = "I heard Caelestites couldn't use Luminatics to fight.",
  ui_story_5026_50260702_11_dialog_content = "You can't use Luminatics to manipulate tools either, like I'm doing right now, so I don't have to perform physical labor on my own.",
  ui_story_5026_50260702_12_dialog_content = "You seem to need to swing your pick three or four times just to chip off a piece of ore...",
  ui_story_5026_50260702_13_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_5026_50260702_14_dialog_content = "Ah! Did that hurt you? Sorry!",
  ui_story_5026_50260702_15_dialog_content = "<anim type=Shake>Chubb...</anim>",
  ui_story_5026_50260702_16_dialog_content = "Even though I can handle weapons quite well, it takes me some time to get used to the weight of these tools and how they're used...",
  ui_story_5026_50260702_17_dialog_content = "Where were we earlier, PlayerName?",
  ui_story_5026_50260702_18_dialog_content = "Oh yes, what I learned about Caelestites' abilities is that they're not all that useful for defending territory...",
  ui_story_5026_50260702_19_dialog_content = "But Caelestites can command Aurorians to fight efficiently, so did your ancestors employ Aurorians as their guards?",
  ui_story_5026_50260702_20_dialog_content = "If there was frequent communication between the two races, there should be more information in Father's library that—",
  ui_story_5026_50260702_21_dialog_content = "<size=45>Whoa!</size>",
  ui_story_5026_50260702_22_dialog_content = "W-What happened? Are they sticking together because they want to get revenge for their friend?",
  ui_story_5026_50260702_23_option_content = "No, I don't think that's it.",
  ui_story_5026_50260702_24_option_content = "Should I try using my ability?",
  ui_story_5026_50260702_25_dialog_content = "(Speaking of which, I've never thought about what goes through the Chubbs' minds.)",
  ui_story_5026_50260702_26_dialog_content = "Help Chubb!",
  ui_story_5026_50260702_27_dialog_content = "You guys... Are you helping me sort through the ores we mined?",
  ui_story_5026_50260702_28_dialog_content = "Chubb!",
  ui_story_5026_50260702_29_dialog_content = "Okay, keep this one. It should be iron, which can be used to make tools.",
  ui_story_5026_50260702_30_dialog_content = "There's quartz too, but the fineness may be a problem, so it can only be used as construction material.",
  ui_story_5026_50260702_31_dialog_content = "Ah, that might be a raw gemstone! Be gentle with it!",
  ui_story_5026_50260702_32_dialog_content = "Got it, Chubb!",
  ui_story_5026_50260702_33_dialog_content = "What adorable... Ahem... I mean, wonderful creatures.",
  ui_story_5026_50260702_34_dialog_content = "It looks like Cloud Gardens has its own unique system for both security and production.",
  ui_story_5026_50260702_35_dialog_content = "(Unique system? I haven't yet taken the time to think about this before.)",
  ui_story_5026_50260702_36_dialog_content = "(My first impression of Nina was that she wasn't well-versed in wordly affairs, and her world domination plan sounded pretty farfetched too.)",
  ui_story_5026_50260702_37_dialog_content = "(But there's no doubt about her professionalism when it comes to business matters!)",
  ui_story_5026_50260702_38_dialog_content = "(Meanwhile I... I don't even know much about this place I call home.)",
  ui_story_5026_50260702_39_dialog_content = "(I'm the one who's on probation here, right? Will I be able to pass?)",
  ui_story_5026_50260702_40_dialog_content = "You seem to be very interested in Cloud Gardens' operations.",
  ui_story_5026_50260702_41_dialog_content = "This is where the world domination plan I came up with begins, after all. It's only natural to learn as much as possible about it, right?",
  ui_story_5026_50260702_42_dialog_content = "You look about the same age as me, but you're really impressive.",
  ui_story_5026_50260702_43_dialog_content = "W-What? You don't have anything to gain from flattering me like that.",
  ui_story_5026_50260702_44_dialog_content = "Next, it's time to tally up our results.",
  ui_story_5026_50260702_45_dialog_content = "I managed to get quite a lot. I won't lose to Minos this time, right?",
  ui_story_5026_50260702_46_dialog_content = "Amazing, Chubb!",
  ui_story_5026_50260702_47_dialog_content = "Master is amazing too, Chubb!",
  ui_story_5026_50260702_48_dialog_content = "Master?",
  ui_story_5026_50260702_49_dialog_content = "There's an even larger pile of ores next to yours. Are these what Minos mined?",
  ui_story_5026_50260702_50_dialog_content = "W-When did you guys get bribed by Minos?!",
  ui_story_5026_50260702_51_dialog_content = "Um... Miss...",
  ui_story_5026_50260702_52_dialog_content = "I mean, Nina!",
  ui_story_5026_50260702_53_dialog_content = "How is it on your end? We agreed on confirming the location of an ore deposit, but I can't dig anymore. And I...",
  ui_story_5026_50260702_54_dialog_content = "... I'm so hungry!",
  ui_story_5026_50260702_55_dialog_content = "Who spoke just now?",
  ui_story_5026_50260702_56_dialog_content = "<size=45>Aaah! M-Manae!</size>",
  ui_story_5026_50260702_57_dialog_content = "No work, no food, I get that... But don't we even get a sip of water after hours of digging?",
  ui_story_5026_50260702_58_dialog_content = "Even the mine we worked in before in the dead of night without the Shadowlord's permission wasn't as exploitive!",
  ui_story_5026_50260702_59_dialog_content = "Manae! Shh!",
  ui_story_5026_50260702_60_dialog_content = "Sorry! I didn't even take that into consideration. I'll get some water for you right now!",
  ui_story_5026_50260702_61_dialog_content = "(Huh? Do dolls need water too?)",
  ui_story_5026_50260702_62_dialog_content = "(I was so preoccupied with getting reprimanded that I apologized to a doll without realizing it...)",
  ui_story_5026_50260702_63_dialog_content = "(No, no, no, more importantly...)",
  ui_story_5026_50260702_64_dialog_content = "<size=45>It talked?!</size>",
  ui_story_5026_50260702_65_dialog_content = "Am I hallucinating because I'm so tired?",
  ui_story_5026_50260702_66_dialog_content = "Why not take a break, Mr. Navigator?",
  ui_story_5026_50260702_67_dialog_content = "Everyone, please sit here.",
  ui_story_5026_50260702_68_dialog_content = "Where did these table and chairs come from?",
  ui_story_5026_50260702_69_dialog_content = "And where did these snacks come from?",
  ui_story_5026_50260702_70_dialog_content = "I borrowed your kitchen with Chubbs' help. Are the snacks to your liking?",
  ui_story_5026_50260702_71_dialog_content = "They're so good...",
  ui_story_5026_50260702_72_dialog_content = "(Waah, I knew it. The poor food in Cloud Gardens wasn't because of the kitchen.)",
  ui_story_5026_50260702_73_dialog_content = "Mr. Navigator, did I scare you earlier?",
  ui_story_5026_50260702_74_dialog_content = "This puppet is Manae. Sometimes she'll open her mouth out of the blue and say uncomfortable things.",
  ui_story_5026_50260702_75_dialog_content = "I know she's just looking out for me, but...",
  ui_story_5026_50260702_76_dialog_content = "Sanae, the tea is overflowing.",
  ui_story_5026_50260702_77_dialog_content = "<size=45>S-Sorry!</size>",
  ui_story_5026_50260702_78_dialog_content = "Two sugar cubes, stirred ten times clockwise and three times counterclockwise. Here, Miss Nina.",
  ui_story_5026_50260702_79_dialog_content = "Uh-hum.",
  ui_story_5026_50260702_80_dialog_content = "(Nina seems used to this...)",
  ui_story_5026_50260702_81_dialog_content = "(Is it really okay for me to be relaxed like this when Eclipsites are running about all over Cloud Gardens?)",
  ui_story_5026_50260702_82_dialog_content = "(But anyways, it's not as if stressing out would fix anything.)",
  ui_story_5026_50260702_83_dialog_content = "(As Nina asked earlier, how did Caelestites defend themselves against intruders in the past?)",
  ui_story_5026_50260702_84_dialog_content = "(Hiring Aurorians as bodyguards was obviously impossible.)",
  ui_story_5026_50260702_85_dialog_content = "(If the Obelisk of Return was the only means of defense here, what should I do now that it has fallen silent?)",
  ui_story_5026_50260702_86_dialog_content = "(Even if there are other weapons left behind by the ancient Caelestites, could their enemies—)",
  ui_story_5026_50260702_87_dialog_content = "What are you thinking so hard about?",
  ui_story_5026_50260702_88_dialog_content = "N-Nothing!",
  ui_story_5026_50260702_89_dialog_content = "Tea time is a sacred time that should not be intruded upon. Do not think about unnecessary things.",
  ui_story_5026_50260702_90_dialog_content = "It's important to allow yourself to slow down once in a while.",
  ui_story_5026_50260702_91_dialog_content = "But if you have any doubts about what we've done so far, feel free to tell us.",
  ui_story_5026_50260702_92_dialog_content = "It's not really doubt, but I am curious about something.",
  ui_story_5026_50260702_93_dialog_content = "What is the relationship between the three of you, and why did you apply for the managerial position at Cloud Gardens?",
  ui_story_5026_50260702_94_dialog_content = "You don't seem to be used to physical labor.",
  ui_story_5026_50260702_95_dialog_content = "Y-You can tell!?",
  ui_story_5026_50260702_96_dialog_content = "And Sanae isn't meticulous enough to be good at housework.",
  ui_story_5026_50260702_97_dialog_content = "B-But I... <size=45>Ahhhh! The cups!</size>",
  ui_story_5026_50260702_98_dialog_content = "Minos on the other hand... is impeccable to the point of horrifying. You can obviously find a better job.",
  ui_story_5026_50260702_99_dialog_content = "Thanks for the compliment, but I am just a simple butler.",
  ui_story_5026_50260702_100_dialog_content = "Don't misunderstand. I'm not criticizing any of you!",
  ui_story_5026_50260702_101_dialog_content = "I'm sure there must be a reason for you guys to have your secrets.",
  ui_story_5026_50260702_102_dialog_content = "Without you, there's no way I could've handled so many Eclipsites.",
  ui_story_5026_50260702_103_dialog_content = "And you guys made me realize that Cloud Gardens need a lot more work.",
  ui_story_5026_50260702_104_dialog_content = "Minos called me the Master of Cloud Gardens, and the Chubbs call me Master as well...",
  ui_story_5026_50260702_105_dialog_content = "But do I really deserve this title?",
  ui_story_5026_50260702_105X1_dialog_content = "Rather than waste time doubting yourself, you should think of what you can do to make yourself deserving of the title.",
  ui_story_5026_50260702_105X2_dialog_content = "At least, that's what I would do.",
  ui_story_5026_50260702_105X3_dialog_content = "But contrary to my suggestion, I think what you need more now is...",
  ui_story_5026_50260702_106_dialog_content = "...",
  ui_story_5026_50260702_107_dialog_content = "PlayerName, is there a place you particularly like in Cloud Gardens?",
  ui_story_5026_50260702_108_dialog_content = "When I need to relax, I go fishing.",
  ui_story_5026_50260702_109_dialog_content = "But I encountered Eclipsites on my way there the last time...",
  ui_story_5026_50260702_110_dialog_content = "Why do you ask, do you want—",
  ui_story_5026_50260702_110X1_dialog_content = "I-It's definitely not because I want you to relax or anything!",
  ui_story_5026_50260702_111_dialog_content = "Knowing my business partners' hobbies is part of the job!",
  ui_story_5026_50260702_112_dialog_content = "Now that you've made your realizations, finish up your tea and let's get going.",
  ui_story_5026_50260801_1_dialog_content = "<color=#e8d9bb>Eraveil: Wilderness</color>",
  ui_story_5026_50260801_2_dialog_content = "Hmm... I'm still a bit concerned.",
  ui_story_5026_50260801_3_dialog_content = "I only learned about the situation at the Andersen home after going back to Umbraton to ask around...",
  ui_story_5026_50260801_4_dialog_content = "What in the world is going on?",
  ui_story_5026_50260801_5_dialog_content = "Oh, hey! We got to the river safely this time!",
  ui_story_5026_50260801_6_dialog_content = "The last time I came fishing, Eclipsites suddenly appeared. I don't know what would've happened if Bethel hadn't been there.",
  ui_story_5026_50260801_7_dialog_content = "I'd probably have pricked myself on a blade of grass considering how much the Spikepest messed the place up.",
  ui_story_5026_50260801_8_dialog_content = "Are you and Bethel very close?",
  ui_story_5026_50260801_9_dialog_content = "We fought side by side with Luke from the White Flame Mercenaries in the Blue Lion Guild incident.",
  ui_story_5026_50260801_10_dialog_content = "We crossed paths sometimes afterward. That time she saved me, she'd actually come on behalf of Sheol and the Cloudrover Guild.",
  ui_story_5026_50260801_11_dialog_content = "Hmph. I see.",
  ui_story_5026_50260801_12_dialog_content = "She's an impressive merchant. She's done a good job managing Istvan's guild.",
  ui_story_5026_50260801_13_dialog_content = "Back at Dawn Academy, everyone also sang Bethel's praises.",
  ui_story_5026_50260801_14_dialog_content = "D-Don't overthink! It's not that I care about what goes on between you two!",
  ui_story_5026_50260801_15_dialog_content = "(So she does care.)",
  ui_story_5026_50260801_16_dialog_content = "You said fishing was part of your daily tasks here, right?",
  ui_story_5026_50260801_17_dialog_content = "If that's the case, it can't be treated like just any casual activity.",
  ui_story_5026_50260801_18_dialog_content = "Once. Just once, I need to beat Minos.",
  ui_story_5026_50260801_19_dialog_content = "However, there was only one fishing rod, and the Chubbs gave it to Minos.",
  ui_story_5026_50260801_20_dialog_content = "What?",
  ui_story_5026_50260801_21_dialog_content = "I know. It's a bit of a hassle without a fishing rod.",
  ui_story_5026_50260801_22_dialog_content = "What makes him so popular among the Chubbs!?",
  ui_story_5026_50260801_23_dialog_content = "So that's what you really care about...",
  ui_story_5026_50260801_24_dialog_content = "Just to even out the odds, I'll teach you how to fish without a fishing rod.",
  ui_story_5026_50260801_25_dialog_content = "In the Far East, everyone calls me the great \"Goldfish Master\"!",
  ui_story_5026_50260801_26_dialog_content = "Even if I don't have the tools I had back there and the fish are different, well... they're still fish, right?",
  ui_story_5026_50260801_27_dialog_content = "...",
  ui_story_5026_50260801_28_dialog_content = "Sanae, you told me once that you used to catch fish in the river when you were young. How about you teach me?",
  ui_story_5026_50260801_29_dialog_content = "(She ignored me!)",
  ui_story_5026_50260801_30_dialog_content = "Ah... Ahaha... haha! I think I saw some fish over there just now. I'll go check it out!",
  ui_story_5026_50260801_31_dialog_content = "PlayerName's gone...",
  ui_story_5026_50260801_32_dialog_content = "Miss Nina, you... Catching fish is beneath you! Please, allow me!",
  ui_story_5026_50260801_33_dialog_content = "Being able to catch a fish or not used to mean the difference between life and death to me.",
  ui_story_5026_50260801_34_dialog_content = "Even though I may not be as good as the renowned PlayerName, I will still give it my best!",
  ui_story_5026_50260801_35_dialog_content = "You called me \"Miss Nina\" again, didn't you?",
  ui_story_5026_50260801_36_dialog_content = "Ah! S-Sorry about that!",
  ui_story_5026_50260801_37_dialog_content = "I'm not concerned about revealing my identity. If I'm not wrong, PlayerName doesn't really care.",
  ui_story_5026_50260801_38_dialog_content = "He's never heard of Count Andersen. I anticipated that.",
  ui_story_5026_50260801_39_dialog_content = "Father may own a lot of land across Astra, but to the Caelestite, he's just any old man.",
  ui_story_5026_50260801_40_dialog_content = "Somehow, that makes me happy.",
  ui_story_5026_50260801_41_dialog_content = "N-Nina...",
  ui_story_5026_50260801_42_dialog_content = "That's right, Sanae. I'm just Nina here. And... catching fish seems fun.",
  ui_story_5026_50260801_43_dialog_content = "I only saw people doing it beside the Gold River whenever I passed by it. I've been itching to try.",
  ui_story_5026_50260801_44_dialog_content = "U-Um Nina... Your dress is a bit long for fishing.",
  ui_story_5026_50260801_45_dialog_content = "It's fine. I'll hold it up.",
  ui_story_5026_50260801_46_dialog_content = "All you need is to tell me how to lock on to the target, and my Luminatics will do the rest.",
  ui_story_5026_50260801_47_dialog_content = "Ah! The water's so cold!",
  ui_story_5026_50260801_48_dialog_content = "The pebbles in the water are slippery. Watch your step!",
  ui_story_5026_50260801_49_dialog_content = "If Mr. Minos were here, he'd probably remind you to mind your status and be elegant.",
  ui_story_5026_50260801_50_dialog_content = "But he seems to be preoccupied with something else right now.",
  ui_story_5026_50260801_51_dialog_content = "Let me show you how to catch fish.",
  ui_story_5026_50260801_52_dialog_content = "First, stand still in the water, just like your feet are rooted into the riverbed.",
  ui_story_5026_50260801_53_dialog_content = "Then observe the motion of the fish, and pick your target.",
  ui_story_5026_50260801_54_dialog_content = "Hey! That's a globefish over there. It's delicious when steamed!",
  ui_story_5026_50260801_55_dialog_content = "That knifefish would make a nice roast...",
  ui_story_5026_50260801_56_dialog_content = "<size=45>Heheh... Hahahahah!</size>",
  ui_story_5026_50260801_57_dialog_content = "W-What? Oh, I'm sorry! I just had snacks, and now I'm...",
  ui_story_5026_50260801_58_dialog_content = "It's fine. I was just thinking, this is so you.",
  ui_story_5026_50260801_59_dialog_content = "You're quite chatty once you find something you enjoy talking about.",
  ui_story_5026_50260801_60_dialog_content = "That's true... Is it weird?",
  ui_story_5026_50260801_61_dialog_content = "On the contrary. I find it quite cute.",
  ui_story_5026_50260801_62_dialog_content = "Hmm... W-Where w-were we just now?",
  ui_story_5026_50260801_63_dialog_content = "Observe the fish and pick your target.",
  ui_story_5026_50260801_64_dialog_content = "Right! Now, make your kill when the fish is still off-guard...",
  ui_story_5026_50260801_65_dialog_content = "<size=45>Now!</size>",
  ui_story_5026_50260801_66_dialog_content = "Gotcha!",
  ui_story_5026_50260801_67_dialog_content = "Amazing!",
  ui_story_5026_50260801_68_dialog_content = "Hehe...",
  ui_story_5026_50260801_69_dialog_content = "Let me try... Whoa! It's so slippery!",
  ui_story_5026_50260801_70_dialog_content = "It got away...",
  ui_story_5026_50260801_71_dialog_content = "Is this how the great Goldfish Master does it, PlayerName? I'm speechless.",
  ui_story_5026_50260801_72_dialog_content = "It's easier said than done! You try!",
  ui_story_5026_50260801_73_dialog_content = "Ha! Just watch me!",
  ui_story_5026_50260801_74_dialog_content = "Miss Nina sure is having fun.",
  ui_story_5026_50260801_75_dialog_content = "Huh? I thought you were catching fish with Nina, PlayerName?",
  ui_story_5026_50260801_76_dialog_content = "She's having a great time with Sanae, so I thought I'd better leave them alone.",
  ui_story_5026_50260801_77_dialog_content = "But why are you back? Hey, did Sheol reject my request to postpone payment?",
  ui_story_5026_50260801_78_dialog_content = "No, that's going smoothly, but...",
  ui_story_5026_50260801_79_dialog_content = "Mr. Minos, is it true that Count Andersen has been turning visitors away due to health concerns?",
  ui_story_5026_50260801_80_dialog_content = "Looks like you've already heard, Lady Bethel.",
  ui_story_5026_50260801_81_dialog_content = "...",
  ui_story_5026_50260801_82_dialog_content = "(Was Minos just evaluating me? Or was I mistaken?)",
  ui_story_5026_50260801_83_dialog_content = "In fact, that happened after Miss Nina ran away from home and said \"I hate you, Papa!\"...",
  ui_story_5026_50260801_84_dialog_content = "The Master canceled all meetings and locked himself inside his room.",
  ui_story_5026_50260801_85_dialog_content = "Wait a minute. Then who's handling all the affairs regarding their properties and lands right now?",
  ui_story_5026_50260801_86_dialog_content = "Thank you for your concern, Lady Bethel.",
  ui_story_5026_50260801_87_dialog_content = "But to me, no affair is more important than both of them.",
  ui_story_5026_50260801_88_dialog_content = "Father! Did you send people to buy all the goods in my store?",
  ui_story_5026_50260801_89_dialog_content = "Nina, my dear, what are you talking about?",
  ui_story_5026_50260801_90_dialog_content = "You cleared out my store to make it seem like they were popular, didn't you?",
  ui_story_5026_50260801_91_dialog_content = "I-I actually thought what I designed was really good... but now...",
  ui_story_5026_50260801_92_dialog_content = "Oh, my dear... Don't be upset!",
  ui_story_5026_50260801_93_dialog_content = "It's my bad! I just want to give you everything you deserve, all the best things!",
  ui_story_5026_50260801_94_dialog_content = "Papa, you're always like this!",
  ui_story_5026_50260801_95_dialog_content = "Every time I think I've finally achieved something on my own, I find out you're pulling strings behind the scenes!",
  ui_story_5026_50260801_96_dialog_content = "Do you think that without your help, without the Andersen name, I'm totally helpless?!",
  ui_story_5026_50260801_97_dialog_content = "N-No! Of course not! It's not like that, Nina!",
  ui_story_5026_50260801_98_dialog_content = "<size=45>I hate you, Papa!</size>",
  ui_story_5026_50260801_99_dialog_content = "And that's how Miss Nina ended up taking Sanae and running away.",
  ui_story_5026_50260801_100_dialog_content = "So the Master sent me after Miss Nina to bring her back... But not against her will.",
  ui_story_5026_50260801_101_dialog_content = "(That sounds like a difficult task.)",
  ui_story_5026_50260801_102_dialog_content = "Not at all. It's part of my job.",
  ui_story_5026_50260801_103_dialog_content = "(Did he just read my mind?)",
  ui_story_5026_50260801_104_dialog_content = "I did not read your mind. Please be at ease.",
  ui_story_5026_50260801_105_dialog_content = "Then how do you know what I'm thinking!?",
  ui_story_5026_50260801_106_dialog_content = "If you don't mind me saying, Mr. Navigator, you're like an open book.",
  ui_story_5026_50260801_107_dialog_content = "But you're unlike anyone Miss Nina has ever met. That may be why she opened up to you.",
  ui_story_5026_50260801_108_dialog_content = "Wow, you call our current interactions as her \"opening\" herself up to me?",
  ui_story_5026_50260801_109_dialog_content = "The shadows are always watching, Mr. Navigator. More than one, actually.",
  ui_story_5026_50260801_110_dialog_content = "I hope you won't ever betray Miss Nina's trust.",
  ui_story_5026_50260801_111_dialog_content = "Do not worry. If worst comes to worst...",
  ui_story_5026_50260801_112_dialog_content = "Ms. Sheol would still make sure that in terms of business, getting fewer half-priced deals would be the only thing you have to contend with.",
  ui_story_5026_50260801_113_dialog_content = "Of course, there'd be consequences not pertaining to business matters as well.",
  ui_story_5026_50260801_114_dialog_content = "No, no, no, say no more. Half-priced deals matter a lot to me!",
  ui_story_5026_50260801_115_dialog_content = "Thank you for your understanding.",
  ui_story_5026_50260801_116_dialog_content = "However, I have to make something clear.",
  ui_story_5026_50260801_117_dialog_content = "To me, Nina is Nina. Neither her status nor identity would change how I see her.",
  ui_story_5026_50260801_118_dialog_content = "She would be grateful to hear you say that... truly.",
  ui_story_5026_50260801_119_dialog_content = "Allow me to ask you something...",
  ui_story_5026_50260801_120_dialog_content = "If she were to get upset at me and run away shouting, \"PlayerName is an idiot!\"... What would happen then?",
  ui_story_5026_50260801_121_dialog_content = "You would die, naturally.",
  ui_story_5026_50260801_122_dialog_content = "(I feel a chill down my spine... I'm sure I didn't imagine it!)",
  ui_story_5026_50260801_123_dialog_content = "That was a joke. I'm no executioner, just a simple butler.",
  ui_story_5026_50260801_124_dialog_content = "(He doesn't look like he's joking at all!)",
  ui_story_5026_50260801_125_dialog_content = "It's been a pleasure chatting with you, Mr. Navigator. How would you like to handle the fish?",
  ui_story_5026_50260801_126_dialog_content = "Wow, this is a lot! And they're all ornamental fish!",
  ui_story_5026_50260801_127_dialog_content = "I had the Chubbs send the edible ones back to the kitchen already.",
  ui_story_5026_50260801_128_dialog_content = "If it's not too much trouble, please put these ornamental fish into the Fountain of Hope by the Hyacinth Tower.",
  ui_story_5026_50260801_129_dialog_content = "As you wish. Now, please excuse me, Lady Bethel, Mr. Navigator.",
  ui_story_5026_50260801_130_dialog_content = "Bethel... Are butlers in Umbraton all like that?",
  ui_story_5026_50260801_131_dialog_content = "Just like how it is in my guild, the Shadowlord also has subordinates that handle different things.",
  ui_story_5026_50260801_132_dialog_content = "You may know some of them. They're good at what they do and will go anything it takes.",
  ui_story_5026_50260801_133_dialog_content = "As for the Andersen Association, Minos handles all of these extraneous \"affairs.\"",
  ui_story_5026_50260801_134_dialog_content = "He's the best of the best, there are no butlers like him.",
  ui_story_5026_50260801_135_dialog_content = "Right... Thanks... Bethel.",
  ui_story_5026_50260801_136_dialog_content = "(Maybe I shouldn't have asked...)",
  ui_story_5026_50260801_137_dialog_content = "Nina, Nina! The fish is coming your way!",
  ui_story_5026_50260801_138_dialog_content = "...",
  ui_story_5026_50260801_139_dialog_content = "Minos, PlayerName, and... Is that Bethel?",
  ui_story_5026_50260801_140_dialog_content = "What are they discussing amongst themselves?",
  ui_story_5026_50260801_141_dialog_content = "Nina, are you listening?",
  ui_story_5026_50260801_142_dialog_content = "Nina is looking in the direction of those three, muttering to herself.",
  ui_story_5026_50260801_143_dialog_content = "She's probably worried that if she can't beat Minos, she'll have to go home with him.",
  ui_story_5026_50260801_144_dialog_content = "Sanae, have you decided who you're gonna help?",
  ui_story_5026_50260801_145_dialog_content = "I-I won't let Nina lose!",
  ui_story_5026_50260801_146_dialog_content = "But if you lose this job, you'll be on the streets again.",
  ui_story_5026_50260801_147_dialog_content = "Stop telling me that! I'm gonna catch that grouper, not even you will distract me!",
  ui_story_5026_50260801_148_dialog_content = "Now!",
  ui_story_5026_50260801_149_dialog_content = "<size=45>Ah!</size>",
  ui_story_5026_50260801_150_dialog_content = "<color=#e8d9bb>Plop...</color>",
  ui_story_5026_50260801_151_dialog_content = "Sanae?",
  ui_story_5026_50260801_152_dialog_content = "Huh!?",
  ui_story_5026_50260901_1_dialog_content = "<anim type=Shake><size=45>A-Achoo!</size></anim>",
  ui_story_5026_50260901_2_dialog_content = "Towel, Chubb!",
  ui_story_5026_50260901_3_dialog_content = "This Chubb is so considerate...",
  ui_story_5026_50260901_4_dialog_content = "It's just a fish. How could you be so careless and fall into the water?",
  ui_story_5026_50260901_5_dialog_content = "You even dropped your precious doll... Manae probably got a scare.",
  ui_story_5026_50260901_6_dialog_content = "I finally found something that I... I'm good at. I just wanted to win...",
  ui_story_5026_50260901_7_dialog_content = "I'm sorry to have troubled you... I should've made sure I was standing properly. I should be the one taking care of you...",
  ui_story_5026_50260901_8_dialog_content = "And I got your skirts wet...",
  ui_story_5026_50260901_9_dialog_content = "I-I'm sorry, Nina, Manae, and Mr. Chubb...",
  ui_story_5026_50260901_10_dialog_content = "A \"thank you\" is all that's needed.",
  ui_story_5026_50260901_11_dialog_content = "Do you still take me for a young mistress even though we're no longer at the mansion?",
  ui_story_5026_50260901_12_dialog_content = "B-But I'm always clumsy and can't do anything for you...",
  ui_story_5026_50260901_13_dialog_content = "What are you talking about? If you hadn't covered for me, there's no way we could've gotten out of the mansion right under Minos' nose!",
  ui_story_5026_50260901_14_dialog_content = "It's a pity that I didn't get to see his expression when he found that hole in the rose fence.",
  ui_story_5026_50260901_15_dialog_content = "I-I'm not very bright... always reading useless novels and daydreaming...",
  ui_story_5026_50260901_16_dialog_content = "What does that have anything to do with you treating me like a normal person?",
  ui_story_5026_50260901_17_dialog_content = "Actually, if it weren't for all your stories about Cloud Island and the mysterious Caelestites...",
  ui_story_5026_50260901_18_dialog_content = "I probably wouldn't have made up my mind to leave Umbraton and see the world through my own eyes.",
  ui_story_5026_50260901_19_dialog_content = "I'd still be sitting in my room, sulking about rain or something.",
  ui_story_5026_50260901_20_dialog_content = "So you don't need to walk on eggshells all the time. Just say what's on your mind.",
  ui_story_5026_50260901_21_dialog_content = "Nina...",
  ui_story_5026_50260901_22_dialog_content = "I don't mean to intrude, but...",
  ui_story_5026_50260901_23_dialog_content = "According to the staffing requirement PlayerName spoke to me about, all we need now is a logger.",
  ui_story_5026_50260901_24_dialog_content = "Hmm...",
  ui_story_5026_50260901_25_dialog_content = "Miss Sanae's clothes are still damp. Why don't we take a break here?",
  ui_story_5026_50260901_26_dialog_content = "Using Luminatics in a warm and dry place will make her clothes dry faster.",
  ui_story_5026_50260901_27_dialog_content = "I'm sorry⁠—I mean, thanks, Lady Bethel.",
  ui_story_5026_50260901_28_dialog_content = "B-But... I've been meaning to ask... What is this place?",
  ui_story_5026_50260901_29_dialog_content = "PlayerName had Chubb bring us here to rest up.",
  ui_story_5026_50260901_30_dialog_content = "It's the closest! And there are towels here, Chubb!",
  ui_story_5026_50260901_31_dialog_content = "But this seems to be Mr. Navigator's room...",
  ui_story_5026_50260901_32_dialog_content = "He's been kind to us. I should try to tidy this place up for him.",
  ui_story_5026_50260901_33_dialog_content = "Y-You mean... This is...",
  ui_story_5026_50260901_34_dialog_content = "I've never been inside a boy's room!",
  ui_story_5026_50260901_35_dialog_content = "W-Why are you covering your eyes, Nina?",
  ui_story_5026_50260901_36_dialog_content = "Reality is quite different from fiction, isn't it?",
  ui_story_5026_50260901_37_dialog_content = "Lady Bethel?",
  ui_story_5026_50260901_38_dialog_content = "Actually, the more important question is, why are you so at ease, Sanae?",
  ui_story_5026_50260901_39_dialog_content = "I... I served many households before I came to the Andersens.",
  ui_story_5026_50260901_40_dialog_content = "So I've cleaned many boys' rooms.",
  ui_story_5026_50260901_41_dialog_content = "I remember things like dirty clothes hiding beneath made beds...",
  ui_story_5026_50260901_42_dialog_content = "Shelves full of figurines that I wasn't allowed to touch even if they were all dusty...",
  ui_story_5026_50260901_43_dialog_content = "Piles of things that would fall on me as soon as I opened the closet...",
  ui_story_5026_50260901_44_dialog_content = "Oh, and underneath the beds—",
  ui_story_5026_50260901_45_dialog_content = "Uh... Nina... Are you all right?",
  ui_story_5026_50260901_46_dialog_content = "That's so frightening... This is the most terrifying place I've been on this trip so far!",
  ui_story_5026_50260901_47_dialog_content = "It's even scarier than crossing a hanging bridge!",
  ui_story_5026_50260901_48_dialog_content = "You're fine, Miss Nina.",
  ui_story_5026_50260901_49_dialog_content = "When facing the unknown, the most important thing is to obtain all possible intel.",
  ui_story_5026_50260901_50_dialog_content = "I once read a novel where the cold male lead had an armory beneath his bed.",
  ui_story_5026_50260901_51_dialog_content = "When assassins intruded into his house, he took out the guns and protected the female lead!",
  ui_story_5026_50260901_52_dialog_content = "Oh... I've read that book too!",
  ui_story_5026_50260901_53_dialog_content = "In another novel, the male lead was a total slacker, but he was loyal to the female lead.",
  ui_story_5026_50260901_54_dialog_content = "However, he had piles of R-rated material underneath his bed.",
  ui_story_5026_50260901_55_dialog_content = "So you enjoy romance novels! Have you ever read⁠—",
  ui_story_5026_50260901_56_dialog_content = "Sanae... I'm going to head out.",
  ui_story_5026_50260901_57_dialog_content = "Nina? Wait for me!",
  ui_story_5026_50260901_58_dialog_content = "It's just tree-chopping. I can do it on my own. Just come by later!",
  ui_story_5026_50260901_59_dialog_content = "Miss Nina's as red as a tomato. I guess she's not used to these kinds of topics...",
  ui_story_5026_50260901_60_dialog_content = "Sanae, did you just say you read \"The Umbraton Seductress\" as well?",
  ui_story_5026_50260901_61_dialog_content = "It's not just the love between the leads, the story of trust and betrayal between the gang members is so enticing too!",
  ui_story_5026_50260901_62_dialog_content = "It really depicts what gang life is like in Umbraton. It's one of my favs!",
  ui_story_5026_50260901_63_dialog_content = "How about \"The Returned Princess of Lumopolis\"?",
  ui_story_5026_50260901_64_dialog_content = "Oh that one, of course! I love the bride kidnapping scene at the royal wedding!",
  ui_story_5026_50260901_65_dialog_content = "I stood in line for so long just to buy the sequel...",
  ui_story_5026_50260901_66_dialog_content = "Ah! Um... did I get too excited?",
  ui_story_5026_50260901_67_dialog_content = "It's okay! I've finally found someone who enjoys what I enjoy. I have so much more to say to you!",
  ui_story_5026_50260901_68_dialog_content = "Nina was right, I'm very talkative when I find something I like to talk about.",
  ui_story_5026_50260901_69_dialog_content = "But I know... It's not just that.",
  ui_story_5026_50260901_70_dialog_content = "For a long time, I thought Manae was the only one who was willing to listen to me talk.",
  ui_story_5026_50260901_71_dialog_content = "Nina taught me there were people in the world that would accept me for who I was.",
  ui_story_5026_50260901_72_dialog_content = "That must be what gave me the strength to chat with you like this.",
  ui_story_5026_50260901_73_dialog_content = "I mean, I do still owe you a huge amount of money for breaking the ship from Cloud Island...",
  ui_story_5026_50260901_74_dialog_content = "The old me w-would never have dared to speak to you...",
  ui_story_5026_50260901_75_dialog_content = "Miss Sanae...",
  ui_story_5026_50260901_76_dialog_content = "Oh! I'll definitely work hard to earn back the money I owe you!",
  ui_story_5026_50260901_77_dialog_content = "Hehe, there's no rush. But enough about business...",
  ui_story_5026_50260901_78_dialog_content = "Let's talk more about \"The Returned Princess of Lumopolis II\"!",
  ui_story_5026_50260902_1_dialog_content = "<color=#e8d9bb>Cloud Gardens: Forest</color>",
  ui_story_5026_50260902_2_dialog_content = "Didn't think I'd run into Eclipsite stragglers along the way. It cost more time than I thought.",
  ui_story_5026_50260902_3_dialog_content = "Thanks for showing me the way.",
  ui_story_5026_50260902_4_dialog_content = "Chubb!",
  ui_story_5026_50260902_5_dialog_content = "Looks like they prefer the shadows of the trees to open grassland.",
  ui_story_5026_50260902_6_dialog_content = "Most animals are scared of Eclipsites. Aren't you?",
  ui_story_5026_50260902_7_dialog_content = "Chubb?",
  ui_story_5026_50260902_8_dialog_content = "What a strange creature. It doesn't seem to know fear.",
  ui_story_5026_50260902_9_dialog_content = "Just like that Caelestite.",
  ui_story_5026_50260902_10_dialog_content = "No, maybe I find it strange only because I'm used to Umbraton...",
  ui_story_5026_50260902_11_dialog_content = "I'm accustomed to being surrounded by people who wear multiple masks.",
  ui_story_5026_50260902_12_dialog_content = "Don't worry! I'll protect you from any Eclipsites!",
  ui_story_5026_50260902_13_dialog_content = "Nina! Over here!",
  ui_story_5026_50260902_14_dialog_content = "How's Sanae? She was completely wet when she got out of the river.",
  ui_story_5026_50260902_15_dialog_content = "She's fine. Bethel is drying her clothes with Luminatics right now.",
  ui_story_5026_50260902_16_dialog_content = "In your room.",
  ui_story_5026_50260902_17_dialog_content = "In my room!?",
  ui_story_5026_50260902_18_dialog_content = "Room with towels! The closest room! Chubb!",
  ui_story_5026_50260902_19_dialog_content = "Did it have to be my room?",
  ui_story_5026_50260902_20_dialog_content = "PlayerName, underneath your bed, you know, um...",
  ui_story_5026_50260902_21_dialog_content = "Oh... Oh no, you found them, didn't you?",
  ui_story_5026_50260902_22_dialog_content = "Wh...",
  ui_story_5026_50260902_23_dialog_content = "<size=45>H-How shameless!</size>",
  ui_story_5026_50260902_24_dialog_content = "What are you talking about?",
  ui_story_5026_50260902_25_dialog_content = "It's just a bag of leftover Crunchy Munchy Crunch and a Pictorial Guide to Nature with missing pages!",
  ui_story_5026_50260902_26_dialog_content = "I have to admit that the room's a bit messy... I was planning on cleaning it up before Vice comes back...",
  ui_story_5026_50260902_27_dialog_content = "What... So that's...",
  ui_story_5026_50260902_28_option_content = "What were you talking about then?",
  ui_story_5026_50260902_29_dialog_content = "Nothing at all!",
  ui_story_5026_50260902_30_option_content = "What else did you expect!?",
  ui_story_5026_50260902_31_dialog_content = "H-How would I know!?",
  ui_story_5026_50260902_32_dialog_content = "Never mind those silly matters. What did you and Minos talk about at the river?",
  ui_story_5026_50260902_33_dialog_content = "Well... Just that you're the daughter of Count Andersen, and how you ran away from home.",
  ui_story_5026_50260902_34_dialog_content = "I knew it.",
  ui_story_5026_50260902_35_dialog_content = "Did he offer to pay you anything you wanted to not hire me?",
  ui_story_5026_50260902_36_dialog_content = "I'd sure like a check that clears all my debts...",
  ui_story_5026_50260902_37_dialog_content = "So you did take him up on the offer?",
  ui_story_5026_50260902_38_dialog_content = "No! Of course not! I was just joking.",
  ui_story_5026_50260902_39_dialog_content = "By the way, wasn't it a good thing that everything in your store was sold out?",
  ui_story_5026_50260902_40_dialog_content = "I mean, people open a shop to make money, don't they?",
  ui_story_5026_50260902_41_dialog_content = "I don't even know which of your words I find more shocking...",
  ui_story_5026_50260902_42_dialog_content = "Well... Eraveil rarely traded with the outside world, and Soroz didn't have much to teach me about it.",
  ui_story_5026_50260902_43_dialog_content = "Never mind. I will bear with your ignorance since you're an important business partner.",
  ui_story_5026_50260902_44_dialog_content = "To me, it's not just about the money.",
  ui_story_5026_50260902_45_dialog_content = "You probably think I'm a princess who doesn't know what life is like for most.",
  ui_story_5026_50260902_46_dialog_content = "Of course I know making a business profitable is no small feat.",
  ui_story_5026_50260902_47_dialog_content = "But what I want is for my designs to earn people's validation.",
  ui_story_5026_50260902_48_dialog_content = "My father was worried that I'd be upset if my things didn't sell, that's why he bought everything.",
  ui_story_5026_50260902_49_dialog_content = "Even if that would upset me, I would've accepted the outcome knowing I'd done my best.",
  ui_story_5026_50260902_50_dialog_content = "Did you know Bethel became the Shadowlord's right hand when she was not much older than me?",
  ui_story_5026_50260902_51_dialog_content = "So your goal is to surpass Bethel and be Umbraton's top merchant?",
  ui_story_5026_50260902_52_dialog_content = "Tch... amateurs can be so simple-minded.",
  ui_story_5026_50260902_53_dialog_content = "Never mind. It doesn't surprise me that you'd think that way.",
  ui_story_5026_50260902_54_dialog_content = "Sure, people often compared me to her at Umbraton's many social events.",
  ui_story_5026_50260902_55_dialog_content = "She is amazing in her own way, but I opened my shops because I wanted to pursue my passions.",
  ui_story_5026_50260902_56_dialog_content = "But don't be fooled, whatever she's capable of, I'll be able to too, one day!",
  ui_story_5026_50260902_57_dialog_content = "O-On my own of course, without relying on my father or anyone else!",
  ui_story_5026_50260902_58_dialog_content = "(Even if she won't admit it, she's still comparing herself to Bethel.)",
  ui_story_5026_50260902_59_dialog_content = "Not relying on anyone... hmm.",
  ui_story_5026_50260902_60_dialog_content = "Nina.",
  ui_story_5026_50260902_61_dialog_content = "Huh? What's with the sudden seriousness?",
  ui_story_5026_50260902_62_dialog_content = "I've never met my parents except in my dreams.",
  ui_story_5026_50260902_63_dialog_content = "As the last Caelestite left on this continent, I was always alone.",
  ui_story_5026_50260902_64_dialog_content = "I used to think I would wait for the end with Soroz underground.",
  ui_story_5026_50260902_65_dialog_content = "But then one day, Vice fell from the sky and brought me into a brand new world.",
  ui_story_5026_50260902_66_dialog_content = "I made a lot of friends throughout our journey, and experienced incredible adventures.",
  ui_story_5026_50260902_67_dialog_content = "When I was helpless and alone, they gave me a lot of support.",
  ui_story_5026_50260902_68_dialog_content = "Without them, I wouldn't be standing here right now.",
  ui_story_5026_50260902_69_dialog_content = "You never fought with them before?",
  ui_story_5026_50260902_70_dialog_content = "Sure we did, but in the end, we always came to an understanding.",
  ui_story_5026_50260902_71_dialog_content = "We'd be forthcoming if we didn't like what the other was doing.",
  ui_story_5026_50260902_72_dialog_content = "Communicate with the people you care about while they're still around. Don't say things you'll regret later.",
  ui_story_5026_50260902_73_dialog_content = "You don't plan on never going home ever, just because you're mad at your father, do you?",
  ui_story_5026_50260902_74_dialog_content = "O-Of course not...",
  ui_story_5026_50260902_75_dialog_content = "If you could tell him what you just said to me today...",
  ui_story_5026_50260902_76_dialog_content = "I'm sure he'd understand, and he'd never make the same mistake again.",
  ui_story_5026_50260902_77_dialog_content = "(He's a man who shuts the world out just because his daughter's mad at him...)",
  ui_story_5026_50260902_78_dialog_content = "Did you try talking to your father before you ran away from home?",
  ui_story_5026_50260902_79_dialog_content = "...",
  ui_story_5026_50260902_80_dialog_content = "Talk to him? ... I understand.",
  ui_story_5026_50260902_81_dialog_content = "But before that, I want to achieve what I set out to achieve.",
  ui_story_5026_50260902_82_dialog_content = "That's the only way to prove to him that I don't need to rely on him to achieve things!",
  ui_story_5026_50260902_83_dialog_content = "We've patrolled all of Cloud Gardens, right?",
  ui_story_5026_50260902_84_dialog_content = "Yeah, we've exterminated all the Eclipsites we encountered.",
  ui_story_5026_50260902_85_dialog_content = "Now that that's done, business operations is next on the list.",
  ui_story_5026_50260902_86_dialog_content = "I thought about turning this place into an idyllic resort and earning my wad of cash from admission and accommodation fees.",
  ui_story_5026_50260902_87_dialog_content = "Accommodation fees? Everyone here is my friend, I would never—",
  ui_story_5026_50260902_88_dialog_content = "Then developing the surrounding land, making it the heart of a great logistics network that encompasses the entire continent.",
  ui_story_5026_50260902_89_dialog_content = "What's a... logistics network?",
  ui_story_5026_50260902_90_dialog_content = "And then using the fascinating Colossus, which is far more advanced than any Aurorian tech, to transport goods.",
  ui_story_5026_50260902_91_dialog_content = "It shouldn't be hard for someone as famous as you to rake in orders, right, PlayerName?",
  ui_story_5026_50260902_92_dialog_content = "I don't think they'd have much business to do with me...",
  ui_story_5026_50260902_93_dialog_content = "There's business everywhere with everyone, PlayerName. It's ultimately about what's being sold.",
  ui_story_5026_50260902_94_dialog_content = "Even the self-sufficient large clients who don't do business with Umbraton guilds...",
  ui_story_5026_50260902_95_dialog_content = "Would not hesitate to try and build a relationship with the Last Caelestite.",
  ui_story_5026_50260902_96_dialog_content = "It wouldn't be too far-fetched to think that all of Astra's economy could one day be at our fingertips...",
  ui_story_5026_50260902_97_dialog_content = "That's really far-fetched...",
  ui_story_5026_50260902_98_dialog_content = "But such is the world domination plan I have made for you.",
  ui_story_5026_50260902_99_dialog_content = "\"Now then, we should get started.\"",
  ui_story_5026_50260902_100_dialog_content = "That's what I wanted to say, but I can see you have something else in mind.",
  ui_story_5026_50260902_101_dialog_content = "Just like you said, it's important to communicate.",
  ui_story_5026_50260902_102_dialog_content = "Especially so if we're interdependent business partners. So go on, say your piece.",
  ui_story_5026_50260902_103_dialog_content = "What do I think...",
  ui_story_5026_50260902_104_dialog_content = "(What kind of place do I want Cloud Gardens to be after removing all the Eclipsites?)",
  ui_story_5026_50260902_105_dialog_content = "(After combing through every inch of this place with my own eyes...)",
  ui_story_5026_50260902_106_dialog_content = "I...",
  ui_story_5026_50260902_107_dialog_content = "Sorry to interrupt, Miss Nina, Mr. Navigator.",
  ui_story_5026_50260902_108_dialog_content = "But there is something I need to report to PlayerName.",
  ui_story_5026_50260902_109_dialog_content = "There were no signs of Eclipsites while we were collecting wood, but now...",
  ui_story_5026_50260902_110_dialog_content = "A group of them is closing in from the forest up ahead.",
  ui_story_5026_50261001_1_dialog_content = "Phew... That should be the last one.",
  ui_story_5026_50261001_2_dialog_content = "PlayerName?",
  ui_story_5026_50261001_3_dialog_content = "What's going on...?",
  ui_story_5026_50261001_4_dialog_content = "I can feel Darkflow surrounding Cloud Gardens...",
  ui_story_5026_50261001_5_dialog_content = "Did my ability go haywire?",
  ui_story_5026_50261001_6_dialog_content = "Something bad is happening!",
  ui_story_5026_50261001_7_dialog_content = "What happened?",
  ui_story_5026_50261001_8_dialog_content = "After we left the dormitory to meet up with you, we saw...",
  ui_story_5026_50261001_9_dialog_content = "You have to see it with your own eyes to believe it. Come, I'll just show you!",
  ui_story_5026_50261001_10_dialog_content = "What's going on... We just cleared this place of all Eclipsites, didn't we?",
  ui_story_5026_50261001_11_dialog_content = "I first thought the Eclipsites found here were just a few stragglers...",
  ui_story_5026_50261001_12_dialog_content = "Then, on my patrol around Cloud Gardens, I realized it probably wasn't that simple.",
  ui_story_5026_50261001_13_dialog_content = "And now...",
  ui_story_5026_50261001_14_dialog_content = "I really am too naive.",
  ui_story_5026_50261001_15_dialog_content = "W-We just need to drive them out, right?",
  ui_story_5026_50261001_16_dialog_content = "I already feel bad not paying you during your probation...",
  ui_story_5026_50261001_17_dialog_content = "But this crisis has far exceeded my expectations.",
  ui_story_5026_50261001_18_dialog_content = "Umbraton would definitely hire permanent mercenaries if one of their towns encountered this many Eclipsites.",
  ui_story_5026_50261001_19_dialog_content = "This would undoubtedly generate extra costs, though.",
  ui_story_5026_50261001_20_dialog_content = "I don't want to be already accumulating debt when Cloud Gardens is just starting development, but it seems like I'm left with no choice...",
  ui_story_5026_50261001_21_dialog_content = "I'll head back to Umbraton and contact mercenaries registered with the Guild Headquarters.",
  ui_story_5026_50261001_22_dialog_content = "It'll be faster flying the Colossus, but you probably don't want to leave Cloud Gardens like this, right, PlayerName?",
  ui_story_5026_50261001_23_dialog_content = "I know you have a limited budget, so I'll do my best to get you discounts!",
  ui_story_5026_50261001_24_dialog_content = "What should we do now, PlayerName?",
  ui_story_5026_50261001_25_dialog_content = "The Eclipsites don't seem to have discovered us yet.",
  ui_story_5026_50261001_26_dialog_content = "Hmm... They don't seem to be moving with any purpose.",
  ui_story_5026_50261001_27_dialog_content = "At least, that means it's not an attack ordered by a high-level Eclipsite.",
  ui_story_5026_50261001_28_dialog_content = "We probably won't be so lucky next time if we don't find a sustainable solution for the long term.",
  ui_story_5026_50261001_29_dialog_content = "I sensed fewer Eclipsite activities around Hyacinth Tower. Let's go wait there for Bethel to get back.",
  ui_story_5026_50261201_1_dialog_content = "(The Obelisk of Return definitely drove out all the Eclipsites present in Eraveil at the time...)",
  ui_story_5026_50261201_2_dialog_content = "(So these Eclipsites must have come from other places.)",
  ui_story_5026_50261201_3_dialog_content = "(Nina was right... Peace is rare and precious...)",
  ui_story_5026_50261201_4_dialog_content = "(I don't even want to know how expensive hiring Umbraton mercenaries longterm might be!)",
  ui_story_5026_50261201_5_dialog_content = "There you are, PlayerName.",
  ui_story_5026_50261201_6_dialog_content = "...",
  ui_story_5026_50261201_7_dialog_content = "Hey, PlayerName!",
  ui_story_5026_50261201_8_dialog_content = "Nina...?",
  ui_story_5026_50261201_9_dialog_content = "I-I didn't come because I was worried or anything!",
  ui_story_5026_50261201_10_dialog_content = "It's just that I can't let your dispirited mood affect business!",
  ui_story_5026_50261201_11_dialog_content = "That's all!",
  ui_story_5026_50261201_12_dialog_content = "So you're here because you care.",
  ui_story_5026_50261201_13_dialog_content = "Ugh... if you must put it that way, I suppose it's not entirely inaccurate.",
  ui_story_5026_50261201_14_dialog_content = "Minos and Sanae are keeping watch. No Eclipsites will get close.",
  ui_story_5026_50261201_15_dialog_content = "Anyway, let's go sit down over there.",
  ui_story_5026_50261201_16_dialog_content = "Why do you seem to have more things on your mind than I do?",
  ui_story_5026_50261201_17_dialog_content = "Minos will be taking me back to Umbraton soon.",
  ui_story_5026_50261201_18_dialog_content = "I made a bet with him. If I beat him in just one thing, he was going to let me be.",
  ui_story_5026_50261201_19_dialog_content = "You didn't have a chance.",
  ui_story_5026_50261201_20_dialog_content = "S-Shut up!",
  ui_story_5026_50261201_21_dialog_content = "I... should have known that Minos wouldn't have agreed if he wasn't confident he would win.",
  ui_story_5026_50261201_22_dialog_content = "Whether it was planting the Unique Trees, digging for treasures, or fishing...",
  ui_story_5026_50261201_23_dialog_content = "I lost that last one as well, didn't I?",
  ui_story_5026_50261201_24_dialog_content = "If we're making comparisons...",
  ui_story_5026_50261201_25_dialog_content = "Minos categorized the lumber he gathered and even noted down the best usage for each type.",
  ui_story_5026_50261201_26_dialog_content = "Apparently, he also used a method called \"selective logging\" to ensure that the remaining trees would grow better.",
  ui_story_5026_50261201_27_dialog_content = "I always just cut whichever tree was closest to me... I didn't even know such a method existed.",
  ui_story_5026_50261201_28_dialog_content = "So that means it didn't matter how much lumber Sanae and I collected... We were destined to lose from the beginning.",
  ui_story_5026_50261201_29_dialog_content = "Well... As our butler, that much skill is to be expected.",
  ui_story_5026_50261201_30_dialog_content = "You're praising him?",
  ui_story_5026_50261201_31_dialog_content = "I'm just owning up to my failures and speaking the truth.",
  ui_story_5026_50261201_32_dialog_content = "But as you may already know, his goal is just to take me home.",
  ui_story_5026_50261201_33_dialog_content = "In the end, you still don't have anyone suitable to manage Cloud Gardens.",
  ui_story_5026_50261201_34_dialog_content = "You don't need to worry about that.",
  ui_story_5026_50261201_35_dialog_content = "It may sound unbelievable, but Minos said...",
  ui_story_5026_50261201_36_dialog_content = "While going through the daily tasks, he managed to teach the Chubb Farmers how to work like him.",
  ui_story_5026_50261201_37_dialog_content = "So that's why they called him \"Master.\"",
  ui_story_5026_50261201_38_dialog_content = "He says that despite being limited by their nature, they're still good apprentices.",
  ui_story_5026_50261201_39_dialog_content = "At the very least, under their care, there shouldn't be any Unique Tree that doesn't grow.",
  ui_story_5026_50261201_40_dialog_content = "Hiring a butler like Minos is probably way out of my budget anyway...",
  ui_story_5026_50261201_41_dialog_content = "I didn't know he even managed to do that... Tch, like defeating me wasn't enough.",
  ui_story_5026_50261201_42_dialog_content = "But... I was thinking that maybe it was indeed a bit reckless to just run away from home like that.",
  ui_story_5026_50261201_43_dialog_content = "Y-You were not the one who put the idea in my head!",
  ui_story_5026_50261201_44_dialog_content = "I'm still angry about my father for what he did, and Minos for siding with Father all the way.",
  ui_story_5026_50261201_45_dialog_content = "But I'm more upset at myself.",
  ui_story_5026_50261201_46_dialog_content = "How arrogant of me to stipulate a grand business plan for you when I can't even deal with the Eclipsite problem.",
  ui_story_5026_50261201_47_dialog_content = "And I totally messed the tree planting work... I'm far from the person I said I was going to be.",
  ui_story_5026_50261201_48_dialog_content = "You didn't mess anything up... though it wasn't great...",
  ui_story_5026_50261201_49_dialog_content = "Hmm? What are you getting at?",
  ui_story_5026_50261201_50_dialog_content = "Nothing! I think your grand business plan is cool! It's quite creative and imaginative!",
  ui_story_5026_50261201_51_dialog_content = "Heh... There couldn't be worse criticism for a business plan.",
  ui_story_5026_50261201_52_dialog_content = "I'll admit that there are a lot of things I need to work out, such as geographical and transportation issues, not to mention...",
  ui_story_5026_50261201_53_dialog_content = "A great business hub needs cafes, restaurants, and amusement parks, just like Umbraton does!",
  ui_story_5026_50261201_54_dialog_content = "Hmm... How should I put it?",
  ui_story_5026_50261201_55_dialog_content = "I don't really see Cloud Gardens becoming a central hub for business...",
  ui_story_5026_50261201_56_dialog_content = "Nor can I imagine Soroz being a business tool.",
  ui_story_5026_50261201_57_dialog_content = "Soroz has a mind of its own.",
  ui_story_5026_50261201_58_dialog_content = "At least... it once did. It raised me.",
  ui_story_5026_50261201_59_dialog_content = "For a long time, it taught me everything I know about the Caelestites.",
  ui_story_5026_50261201_60_dialog_content = "(What would it say if it were to see me now...?)",
  ui_story_5026_50261201_61_dialog_content = "I see. I apologize for not being considerate enough.",
  ui_story_5026_50261201_62_dialog_content = "Then, tell me what you have in mind.",
  ui_story_5026_50261201_63_dialog_content = "What?",
  ui_story_5026_50261201_64_dialog_content = "What do you want Cloud Gardens to become?",
  ui_story_5026_50261201_65_dialog_content = "...",
  ui_story_5026_50261201_66_dialog_content = "In Eraveil, a Caelestite once defected to the Eclipsites to gain power at the cost of my entire race.",
  ui_story_5026_50261201_67_dialog_content = "The method she used to pursue power was completely wrong, there's no denying that.",
  ui_story_5026_50261201_68_dialog_content = "But I've been thinking...",
  ui_story_5026_50261201_69_dialog_content = "Were there other things that drove her down that path other than arrogance and cowardice?",
  ui_story_5026_50261201_70_dialog_content = "I still don't know the full story. All I know are bits and pieces.",
  ui_story_5026_50261201_71_dialog_content = "I only know that even at the very end, she didn't get the peace and quiet she wanted.",
  ui_story_5026_50261201_72_dialog_content = "So... I want to make this place a peaceful, serene haven for all.",
  ui_story_5026_50261201_73_dialog_content = "A different place from the Eraveil that belonged to my ancestors.",
  ui_story_5026_50261201_74_dialog_content = "PlayerName...",
  ui_story_5026_50261201_75_dialog_content = "You put it well. Even I'm a bit—no, I'm very moved by your words.",
  ui_story_5026_50261201_76_dialog_content = "But, I need specifics. What do you plan to build here?",
  ui_story_5026_50261201_77_dialog_content = "You're so pragmatic... I think I had a similar conversation with Bethel before.",
  ui_story_5026_50261201_78_dialog_content = "It's called being practical. You better get used to how we do things in Umbraton.",
  ui_story_5026_50261201_79_dialog_content = "According to what Bethel wrote in the recruitment notice, turning a profit is a must, isn't it?",
  ui_story_5026_50261201_80_dialog_content = "Yeah... Who knew Sheol's intel would be so expensive...",
  ui_story_5026_50261201_81_dialog_content = "Underestimating the value of a piece of intel... What a noob.",
  ui_story_5026_50261201_82_dialog_content = "Is there any way to earn loads of Nightium at once, like winning a lottery?",
  ui_story_5026_50261201_83_dialog_content = "PlayerName, do you know anything about grey businesses?",
  ui_story_5026_50261201_84_dialog_content = "It sounds sketchy...",
  ui_story_5026_50261201_85_dialog_content = "Massive short-term profit from unknown sources. Many guilds in Umbraton have such resources...",
  ui_story_5026_50261201_86_dialog_content = "Including the Andersens, before my father took over.",
  ui_story_5026_50261201_87_dialog_content = "Did I just hear something that I shouldn't have?",
  ui_story_5026_50261201_88_dialog_content = "I'm not asking you to do the same, I was just bringing it up as an option.",
  ui_story_5026_50261201_89_dialog_content = "How can anyone be at ease making money without knowing where it's coming from, especially considering someone could've been harmed in the process?",
  ui_story_5026_50261201_90_dialog_content = "I don't know about the others, but for my father, they came as an inheritance.",
  ui_story_5026_50261201_91_dialog_content = "Even though he got our family out of such shady businesses, he couldn't do anything about a past legacy he had no control over.",
  ui_story_5026_50261201_92_dialog_content = "However, he was able to decide how to utilize that inheritance.",
  ui_story_5026_50261201_93_dialog_content = "Once, he said something to me after we visited the clinics and orphanages funded by the Andersens.",
  ui_story_5026_50261201_94_dialog_content = "\"The past is in the past. Today and tomorrow, however, are still in our hands.\"",
  ui_story_5026_50261201_95_dialog_content = "Some in Umbraton consider the charity pity of the rich, a declining noble's arrogance, or even a viper's poison in disguise...",
  ui_story_5026_50261201_96_dialog_content = "Hmph! Maybe they think they can ascend Lumopolis on their ivory ladder of morality!",
  ui_story_5026_50261201_97_dialog_content = "But I've seen with my own eyes how many benefited from the inheritance.",
  ui_story_5026_50261201_98_dialog_content = "I wonder if Father has been taking care of himself while I've been gone...",
  ui_story_5026_50261201_99_dialog_content = "If he were here, he'd be able to give you better advice, PlayerName.",
  ui_story_5026_50261201_100_dialog_content = "I-I digress... Anyway...",
  ui_story_5026_50261201_101_dialog_content = "Nina, you actually love your father a lot, don't you?",
  ui_story_5026_50261201_102_dialog_content = "What gave you that idea!? Fine. It's my fault for straying off topic first...",
  ui_story_5026_50261201_103_dialog_content = "I wouldn't really call it digressing.",
  ui_story_5026_50261201_104_dialog_content = "Cloud Gardens and the Chubbs are... my inheritance, in a manner of speaking.",
  ui_story_5026_50261201_105_dialog_content = "But for a myriad of reasons, I haven't been able to pay it much attention until now.",
  ui_story_5026_50261201_106_dialog_content = "Maybe there'll be some unexpected gain out of all this...",
  ui_story_5026_50261201_107_dialog_content = "<size=45>I agree!</size>",
  ui_story_5026_50261201_108_dialog_content = "Uh... what?",
  ui_story_5026_50261201_109_dialog_content = "You don't pay enough attention to the Chubbs!",
  ui_story_5026_50261201_110_dialog_content = "Even if I'm more accustomed to noticing details in physical appearances, being a designer and all...",
  ui_story_5026_50261201_111_dialog_content = "How can you not tell the difference between the Chubbs?",
  ui_story_5026_50261201_112_dialog_content = "Even if you can't tell just by looking at them, according to Sanae they also have different personalities.",
  ui_story_5026_50261201_113_dialog_content = "Different personalities? Really?",
  ui_story_5026_50261201_114_dialog_content = "Sanae felt sorry about thinking they were the same, so she paid more attention to them.",
  ui_story_5026_50261201_115_dialog_content = "But you shouldn't need to be as observant as her to tell. I mean, you should already know that after spending so much time with them.",
  ui_story_5026_50261201_116_dialog_content = "PlayerName, have you ever thought about training your employees periodically?",
  ui_story_5026_50261201_117_dialog_content = "Or working with them to solve issues you encounter when managing the business?",
  ui_story_5026_50261201_118_dialog_content = "Although... there's no business to talk about if we don't get rid of the Eclipsites first...",
  ui_story_5026_50261201_119_dialog_content = "You become so terrifying as soon as you start talking about business matters...",
  ui_story_5026_50261201_120_dialog_content = "<size=45>S-Shut up!</size> I'm trying to help you!",
  ui_story_5026_50261201_121_dialog_content = "I know, and I'm thankful, Nina.",
  ui_story_5026_50261201_122_dialog_content = "Thanks to what you said earlier, I actually thought of something. Of course, I need to try it out first.",
  ui_story_5026_50261201_123_dialog_content = "I'm going to try acting as the Master of Cloud Gardens...",
  ui_story_5026_50261201_124_dialog_content = "A Caelestite method.",
  ui_story_5026_50261301_1_dialog_content = "What are you looking for in the bushes? I don't think there's anything in there.",
  ui_story_5026_50261301_2_dialog_content = "What kind of Caelestite method is this?",
  ui_story_5026_50261301_3_dialog_content = "I knew it. These ruins are exactly the same as the buildings I restored using the blueprints.",
  ui_story_5026_50261301_4_dialog_content = "Dormitories, wells... By the looks of it, Cloud Gardens definitely used to be a large residential area.",
  ui_story_5026_50261301_5_dialog_content = "But, there are very few signs of any sentry posts.",
  ui_story_5026_50261301_6_dialog_content = "Since the defensive measures at the Obelisk of Return are really hard to activate...",
  ui_story_5026_50261301_7_dialog_content = "It's likely that Cloud Gardens has its own set of automated defensive measures.",
  ui_story_5026_50261301_8_dialog_content = "Not bad, PlayerName!",
  ui_story_5026_50261301_9_option_content = "Impressed?",
  ui_story_5026_50261301_10_dialog_content = "J-Just a bit.",
  ui_story_5026_50261301_11_option_content = "Hehe.",
  ui_story_5026_50261301_12_dialog_content = "Don't be too full of yourself.",
  ui_story_5026_50261301_13_dialog_content = "I didn't think studying those blueprints would be so helpful.",
  ui_story_5026_50261301_14_dialog_content = "That reminds me... Maybe it knows about the defensive measures.",
  ui_story_5026_50261301_15_dialog_content = "<anim type=Shake>Huff, puff...</anim>",
  ui_story_5026_50261301_16_dialog_content = "Wake up! Wake up!",
  ui_story_5026_50261301_17_dialog_content = "A Chubb with a long mustache... it looks fluffy.",
  ui_story_5026_50261301_18_dialog_content = "Oh, it's the Master! Did you find new blueprints, Chubb?",
  ui_story_5026_50261301_19_dialog_content = "I'm not here because of blueprints today.",
  ui_story_5026_50261301_20_dialog_content = "I want to know if there are any defense systems here in Cloud Gardens.",
  ui_story_5026_50261301_21_dialog_content = "Sure. Chubb.",
  ui_story_5026_50261301_22_dialog_content = "Really?! Why didn't you tell me earlier?",
  ui_story_5026_50261301_23_dialog_content = "Master didn't ask earlier, Chubb.",
  ui_story_5026_50261301_24_dialog_content = "Something this important should've been made known to me before teaching me how to plant trees!",
  ui_story_5026_50261301_25_dialog_content = "I don't understand. Come again, Chubb?",
  ui_story_5026_50261301_26_dialog_content = "(I'm suddenly remembering how frustrating it was trying to talk to Neural Aux back in the Obelisk of Return...)",
  ui_story_5026_50261301_27_dialog_content = "How do I activate this defense system?",
  ui_story_5026_50261301_28_dialog_content = "You can activate or disable the targeted defense system from the control terminal in the Hyacinth Tower, Chubb.",
  ui_story_5026_50261301_29_dialog_content = "How do I get to the control terminal?",
  ui_story_5026_50261301_30_dialog_content = "Confidential information accessed. Switching interaction mode. Verifying access...",
  ui_story_5026_50261301_31_dialog_content = "Target: PlayerName, the Last Caelestite.",
  ui_story_5026_50261301_32_dialog_content = "Verifying \"Defender\" class code... Verification failed.",
  ui_story_5026_50261301_33_dialog_content = "Terminating verification process...",
  ui_story_5026_50261301_34_dialog_content = "Highest Decree verified.",
  ui_story_5026_50261301_35_dialog_content = "PlayerName's commands must be followed, PlayerName's wishes brought to fruition.",
  ui_story_5026_50261301_36_dialog_content = "Access verified. Confidential information unlocked.",
  ui_story_5026_50261301_37_dialog_content = "PlayerName the Caelestite.",
  ui_story_5026_50261301_38_dialog_content = "Yes! I'm here!",
  ui_story_5026_50261301_39_dialog_content = "It suddenly feels like we're talking to an elder...",
  ui_story_5026_50261301_40_dialog_content = "To turn over the workbench and access the control terminal, you need to mind-link with four or more Chubbs and synthesize the Secret Key.",
  ui_story_5026_50261301_41_dialog_content = "Confidential information relayed. Switching interaction mode.",
  ui_story_5026_50261301_42_dialog_content = "A-Anything else?",
  ui_story_5026_50261301_43_dialog_content = "<anim type=Shake>Snore...</anim>",
  ui_story_5026_50261301_44_dialog_content = "<size=45>It dozed off!</size>",
  ui_story_5026_50261301_45_dialog_content = "The workbench must be the thing I use to make furniture... So the control terminal is beneath it?",
  ui_story_5026_50261301_46_dialog_content = "I smacked it quite hard the last time when I was making a table... Hopefully I didn't damage it.",
  ui_story_5026_50261301_47_dialog_content = "Instead of worrying about that, why don't you just go and find three more Chubbs first?",
  ui_story_5026_50261301_48_dialog_content = "Right. There's probably going to be some battles along the way.",
  ui_story_5026_50261301_49_dialog_content = "I guess I'll have to help you out once more. No matter what Eclipsites we encounter, I shall—",
  ui_story_5026_50261301_50_dialog_content = "I-I mean, Sanae and I and everyone, shall protect you!",
  ui_story_5026_50261301_51_dialog_content = "Just live up to your role as the commander. Don't slow me down!",
  ui_story_5026_50261402_1_dialog_content = "Hah! Here works, right?",
  ui_story_5026_50261402_2_dialog_content = "Now we have all the Chubbs we need.",
  ui_story_5026_50261402_3_dialog_content = "But I want to be held a bit longer, Chubb.",
  ui_story_5026_50261402_4_dialog_content = "Hmm... Then, how about I—",
  ui_story_5026_50261402_5_dialog_content = "Sanae, just ignore it.",
  ui_story_5026_50261402_6_dialog_content = "(I'm beginning to understand what Sanae meant by them having different personalities...)",
  ui_story_5026_50261402_7_dialog_content = "(And just between these four Chubbs, I can actually tell them apart by their looks.)",
  ui_story_5026_50261402_8_dialog_content = "So what I need to do is mind-link with them to synthesize the Secret Key? That's it?",
  ui_story_5026_50261402_9_dialog_content = "If you wish, you may begin linking to the Chubbs in order.",
  ui_story_5026_50261402_10_dialog_content = "In order?",
  ui_story_5026_50261402_11_dialog_content = "Chubb Scholar is third, Chubb.",
  ui_story_5026_50261402_12_dialog_content = "And Elder Chubb is second, Chubb.",
  ui_story_5026_50261402_13_dialog_content = "Okay... Then...",
  ui_story_5026_50261402_14_dialog_content = "Chubb Merchant should be third, Chubb.",
  ui_story_5026_50261402_15_dialog_content = "Wait, what?",
  ui_story_5026_50261402_16_dialog_content = "Chubb Merchant thinks Chubb Scholar is first, Chubb.",
  ui_story_5026_50261402_17_dialog_content = "Chubb Farmer is first, Chubb.",
  ui_story_5026_50261402_18_dialog_content = "Chubb Farmer remembers the Elder Chubb is supposed to be fourth, Chubb.",
  ui_story_5026_50261402_19_dialog_content = "Even you're acting like you're knowledgeable...",
  ui_story_5026_50261402_20_dialog_content = "Can't you all just tell me the sequence? Elder Chubb must know for sure, right?",
  ui_story_5026_50261402_21_dialog_content = "I'm old and I don't remember, Chubb.",
  ui_story_5026_50261402_22_dialog_content = "<size=45>You memory was perfectly fine just a moment ago!</size>",
  ui_story_5026_50261402_23_dialog_content = "But I do know their words are half right and half wrong, Chubb.",
  ui_story_5026_50261402_24_dialog_content = "So... I can't successfully link up unless I get the order right?",
  ui_story_5026_50261402_25_dialog_content = "Sure you can, but then you'll forgo the pleasure of having solved a puzzle, Chubb.",
  ui_story_5026_50261402_26_dialog_content = "The Master must know how to solve it. Chubb?",
  ui_story_5026_50261402_27_option_content = "Of course I do!",
  ui_story_5026_50261402_28_dialog_content = "The order is: farmer, elder, merchant, scholar.",
  ui_story_5026_50261402_29_dialog_content = "Correct! As expected of the Master!",
  ui_story_5026_50261402_30_option_content = "This isn't the time for games.",
  ui_story_5026_50261402_31_dialog_content = "Chubb...",
  ui_story_5026_50261402_32_dialog_content = "Let's begin.",
  ui_story_5026_50261402_33_option_content = "Perform mind link",
  ui_story_5026_50261402_34_dialog_content = "Secret Key synthesized. Operator login name: \"PlayerName,\" Chubb.",
  ui_story_5026_50261402_35_dialog_content = "Verification in progress. Please hold onto the Chubb that has taken on the Secret Key's form.",
  ui_story_5026_50261402_36_dialog_content = "This thing in my hand is talking to me?",
  ui_story_5026_50261402_37_dialog_content = "It's much lighter than it looks.",
  ui_story_5026_50261402_38_dialog_content = "Operator verification complete, Chubb.",
  ui_story_5026_50261402_39_dialog_content = "I didn't expect it to still talk like a Chubb after becoming like this.",
  ui_story_5026_50261402_40_dialog_content = "I don't know if I should call it cool or cute. Neither seems right.",
  ui_story_5026_50261402_41_dialog_content = "The two pointed ears at the tip seem to match the slot on the workbench.",
  ui_story_5026_50261402_42_dialog_content = "Can... it serve as a weapon too?",
  ui_story_5026_50261402_43_dialog_content = "Warning. Please do not use it for purposes other than unlocking the Hyacinth Tower control terminal, Chubb.",
  ui_story_5026_50261402_44_dialog_content = "Please place the Secret Key into the slot to engage manual connection, Chubb.",
  ui_story_5026_50261402_45_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5026_50261402_46_dialog_content = "Connected.",
  ui_story_5026_50261402_47_dialog_content = "Attempting to establish a connection with the Obelisk of Return... Failed. Obelisk of Return offline.",
  ui_story_5026_50261402_48_dialog_content = "Defense System Status: Disabled.",
  ui_story_5026_50261402_49_dialog_content = "Operator and the control terminal are in mind-link mode.",
  ui_story_5026_50261402_50_dialog_content = "How does this defense system work, exactly?",
  ui_story_5026_50261402_51_dialog_content = "Retrieving help document...",
  ui_story_5026_50261402_52_dialog_content = "The defense system activates a <color=#FFB400>force field</color> that surrounds the residential area with the Hyacinth Tower at the center.",
  ui_story_5026_50261402_53_dialog_content = "The force field will repel all lifeforms labeled as hostile.",
  ui_story_5026_50261402_54_dialog_content = "A force field that keeps enemies out...",
  ui_story_5026_50261402_55_dialog_content = "It's far from the Chord of the Law, but it's not like we have any other choice right now.",
  ui_story_5026_50261402_56_dialog_content = "Current Hostile Target Setting: Aurorians.",
  ui_story_5026_50261402_57_dialog_content = "Please issue a command.",
  ui_story_5026_50261402_58_dialog_content = "<size=45>!!!</size>",
  ui_story_5026_50261402_59_dialog_content = "Hey, PlayerName? Hello?",
  ui_story_5026_50261402_60_dialog_content = "N-Nina! I can explain. What you've just heard—",
  ui_story_5026_50261402_61_dialog_content = "I haven't heard anything since you picked that key up.",
  ui_story_5026_50261402_62_dialog_content = "You just put the key in without a word, but you looked so grim, that's why I...",
  ui_story_5026_50261402_63_dialog_content = "You... didn't hear anything?",
  ui_story_5026_50261402_64_dialog_content = "(So the key and terminal were all communicating with me telepathically?)",
  ui_story_5026_50261402_65_dialog_content = "(Maybe this is just how Caelestites communicated with their creations...)",
  ui_story_5026_50261402_66_dialog_content = "Is this... a-a Caelestite weapon?",
  ui_story_5026_50261402_67_dialog_content = "Looks quite unique.",
  ui_story_5026_50261402_68_dialog_content = "Even though it's just a key, I know what you mean, Sanae.",
  ui_story_5026_50261402_69_dialog_content = "Four Chubbs stacked together!",
  ui_story_5026_50261402_70_dialog_content = "It's totally killing me with cuteness!",
  ui_story_5026_50261402_71_dialog_content = "(Right...)",
  ui_story_5026_50261402_72_dialog_content = "(Whatever the truth is, I won't waver from the choices I've made.)",
  ui_story_5026_50261402_73_dialog_content = "(Now, I need to dive back into the link...)",
  ui_story_5026_50261402_74_dialog_content = "(Hmm... It's like... Once you notice you're breathing, it's hard to do it naturally.)",
  ui_story_5026_50261402_75_dialog_content = "(Focus!)",
  ui_story_5026_50261402_76_dialog_content = "Terminal System, can you hear me?",
  ui_story_5026_50261402_77_dialog_content = "Awaiting command input.",
  ui_story_5026_50261402_78_dialog_content = "Mark all Eclipsites as hostiles. Activate the defense system.",
  ui_story_5026_50261402_79_dialog_content = "Command confirmed. Target: Eclipsites.",
  ui_story_5026_50261402_80_dialog_content = "Force Field Startup Progress: 36%... 67%... 100%.",
  ui_story_5026_50261402_81_dialog_content = "<color=#FFB400>Begin sonata resonance</color>.",
  ui_story_5026_50261501_1_dialog_content = "I-Is it over?",
  ui_story_5026_50261501_2_dialog_content = "The markings on the Hyacinth Tower flashed, but Cloud Gardens doesn't seem to be any different.",
  ui_story_5026_50261501_3_dialog_content = "Could it have failed? The technology is ancient, after all.",
  ui_story_5026_50261501_4_dialog_content = "Well... Even though I can't see anything, I can sense that something is different.",
  ui_story_5026_50261501_5_dialog_content = "The defense system is activated. Eclipsites will not be able to approach the force field, Chubb.",
  ui_story_5026_50261501_6_dialog_content = "That's great...",
  ui_story_5026_50261501_7_dialog_content = "This applies to Eclipsites both outside the force field and inside it, Chubb.",
  ui_story_5026_50261501_8_dialog_content = "What? So if they try to avoid the force field's wall, doesn't that mean...",
  ui_story_5026_50261501_9_dialog_content = "They will congregate at the center of Cloud Gardens, which is here at the Hyacinth Tower, Chubb.",
  ui_story_5026_50261501_10_dialog_content = "You should've told me that before I activated the defenses!",
  ui_story_5026_50261501_11_dialog_content = "PlayerName didn't ask. Chubb.",
  ui_story_5026_50261501_12_dialog_content = "I... I'm beginning to think you're hiding an agenda underneath your cute facade.",
  ui_story_5026_50261501_13_dialog_content = "I don't understand. Come again, Chubb?",
  ui_story_5026_50261501_14_dialog_content = "While we're on the topic of important info—What power source does the defense system draw from? It's not gonna suddenly run out of power, is it?",
  ui_story_5026_50261501_15_dialog_content = "The kinetic energy generated by Chubbs while moving provides power for other Chubbs and the Hyacinth Tower. Chubb.",
  ui_story_5026_50261501_16_dialog_content = "So you Chubbs haven't just been wandering around aimlessly...",
  ui_story_5026_50261501_17_dialog_content = "In that case, can Chubbs fight?",
  ui_story_5026_50261501_18_dialog_content = "Maybe something like combining yourselves to form a giant Chubb via the mind link—",
  ui_story_5026_50261501_19_dialog_content = "Absolutely not, Chubb.",
  ui_story_5026_50261501_20_dialog_content = "That was a fast no!",
  ui_story_5026_50261501_21_dialog_content = "At least there won't be more Eclipsites invading this place, right?",
  ui_story_5026_50261501_22_dialog_content = "Therefore, don't look so upset. You've done the best you can, PlayerName.",
  ui_story_5026_50261501_23_dialog_content = "Is hiring mercenaries from Umbraton the only choice I have now...?",
  ui_story_5026_50261501_24_dialog_content = "My debts just keep accumulating. Vice is going to be shocked when she returns...",
  ui_story_5026_50261501_25_dialog_content = "Well, I did the best I can. There's nothing to complain about.",
  ui_story_5026_50261501_26_dialog_content = "If only I noticed Cloud Gardens' security issues way earlier, none of this would've happened.",
  ui_story_5026_50261501_27_dialog_content = "PlayerName...",
  ui_story_5026_50261501_28_dialog_content = "Miss Nina, we should return to Umbraton now.",
  ui_story_5026_50261501_29_dialog_content = "Right now? But PlayerName is in a bind right now!",
  ui_story_5026_50261501_30_dialog_content = "All there is left to do is to make it to the force field and wait for Lady Bethel's help.",
  ui_story_5026_50261501_31_dialog_content = "If that can be done, then the Eclipsites should no longer pose a threat.",
  ui_story_5026_50261501_32_dialog_content = "Please forgive me for being frank, Miss, but there's nothing more you and I can do.",
  ui_story_5026_50261501_33_dialog_content = "How can you say that!? That's cold, even for you, Minos.",
  ui_story_5026_50261501_34_dialog_content = "Even if we can't kill all the Eclipsites, we should still do what we can before reinforcements arrive!",
  ui_story_5026_50261501_35_dialog_content = "Otherwise, PlayerName would be broke, living on the streets and selling Chubbs to make a living!",
  ui_story_5026_50261501_36_dialog_content = "I-It won't come to that! ... I think.",
  ui_story_5026_50261501_37_dialog_content = "Combat isn't your strength, Miss Nina. How much help can you be?",
  ui_story_5026_50261501_38_dialog_content = "I do not want to see you get hurt in an unnecessary fight.",
  ui_story_5026_50261501_39_dialog_content = "An unnecessary fight?",
  ui_story_5026_50261501_40_dialog_content = "Anything PlayerName needs help with is far from unnecessary to me!",
  ui_story_5026_50261501_41_dialog_content = "Leaving the job to the professionals is the most efficient and effective solution.",
  ui_story_5026_50261501_42_dialog_content = "In other words, you think I'm so fragile and feeble that just a few Eclipsites would hurt me?",
  ui_story_5026_50261501_43_dialog_content = "You're twisting my words, Miss. I'm only asking you to abide by your promise.",
  ui_story_5026_50261501_44_dialog_content = "If you insist, then please convince me through actions.",
  ui_story_5026_50261501_45_dialog_content = "Fine. If that's what you want.",
  ui_story_5026_50261501_46_dialog_content = "Take out your weapon.",
  ui_story_5026_50261501_47_dialog_content = "I'll show you how much my combat skills have improved.",
  ui_story_5026_50261501_48_dialog_content = "I'm glad to hear that. However, it wouldn't matter even if all of you were to gang up on me.",
  ui_story_5026_50261501_49_option_content = "How did it come to this!?",
  ui_story_5026_50261501_50_dialog_content = "N-Nina! I'll help you!",
  ui_story_5026_50261501_51_option_content = "Stop fighting over me already!",
  ui_story_5026_50261501_52_dialog_content = "We're NOT fighting over you! I just hate how he always acts like he's doing what's best for me!",
  ui_story_5026_50261501_53_dialog_content = "It seems that I have no other choice.",
  ui_story_5026_50261502_1_dialog_content = "That's terrifying... It went through the ground like a hot knife through butter...",
  ui_story_5026_50261502_2_dialog_content = "Do you have enough ammo, Miss?",
  ui_story_5026_50261502_3_dialog_content = "<size=45>Stop underestimating me!</size>",
  ui_story_5026_50261502_4_dialog_content = "He's provoking you, Nina! This isn't the time!",
  ui_story_5026_50261502_5_dialog_content = "Sanae, cover the right side!",
  ui_story_5026_50261502_6_dialog_content = "G-Got it! Are you ready, Manae?",
  ui_story_5026_50261502_7_dialog_content = "I wouldn't miss the chance to beat up my superior!",
  ui_story_5026_50261502_8_dialog_content = "Just evade his next attack—",
  ui_story_5026_50261502_9_dialog_content = "<size=45>That's it! Right now!</size>",
  ui_story_5026_50261502_10_dialog_content = "I-I'm exhausted...",
  ui_story_5026_50261502_11_dialog_content = "How about it now? H... *pants* Had enough yet?",
  ui_story_5026_50261502_12_dialog_content = "(Even if I can predict his actions to a degree via my ability... It's hard to keep up.)",
  ui_story_5026_50261502_13_dialog_content = "(It was a close win... I can only hope I'll never have to go up against Minos again...)",
  ui_story_5026_50261502_14_dialog_content = "I am impressed.",
  ui_story_5026_50261502_15_dialog_content = "Miss Nina, Sanae, and PlayerName...",
  ui_story_5026_50261502_16_dialog_content = "Your performance exceeded my expectations.",
  ui_story_5026_50261502_17_dialog_content = "How long it's been since I last tasted defeat...",
  ui_story_5026_50261502_18_dialog_content = "Congratulations, Miss Nina. You've won.",
  ui_story_5026_50261502_19_dialog_content = "Both this battle, and our deal.",
  ui_story_5026_50261502_20_dialog_content = "If you can beat me in \"<color=#FFB400>just one thing</color> in Cloud Gardens,\" you win.",
  ui_story_5026_50261502_21_dialog_content = "The battle met those conditions perfectly.",
  ui_story_5026_50261502_22_dialog_content = "I'd better be more careful when making a verbal agreement next time.",
  ui_story_5026_50261502_23_dialog_content = "Minos, you...",
  ui_story_5026_50261502_24_dialog_content = "Please mind your language, Miss. Always maintain the elegance of a lady.",
  ui_story_5026_50261502_25_dialog_content = "I didn't say anything yet!",
  ui_story_5026_50261502_26_dialog_content = "Yes, I did not use my full strength in our battle.",
  ui_story_5026_50261502_27_dialog_content = "However, you've still proven that you're capable of taking care of yourself on this perilous continent.",
  ui_story_5026_50261502_28_dialog_content = "The companions you have chosen are not servants, but friends who will stand by your side.",
  ui_story_5026_50261502_29_dialog_content = "Mr. Minos...",
  ui_story_5026_50261502_30_dialog_content = "I will report this to Master Andersen.",
  ui_story_5026_50261502_31_dialog_content = "As per our agreement, I should take my leave of you now, but I feel very apologetic.",
  ui_story_5026_50261502_32_dialog_content = "As can clearly be witnessed, I severely damaged Cloud Gardens in our battle.",
  ui_story_5026_50261502_33_dialog_content = "I was a guest, but I destroyed PlayerName's and the Chubbs' home...",
  ui_story_5026_50261502_34_dialog_content = "Even though you are only my temporary employer and apprentices, I've betrayed your trust.",
  ui_story_5026_50261502_35_dialog_content = "Mr. Navigator, I am terribly sorry about this.",
  ui_story_5026_50261502_36_dialog_content = "I know there's no way I can compensate you for what I did to the things you hold dear...",
  ui_story_5026_50261502_37_dialog_content = "But please allow me the chance to make up for what I've done by restoring Cloud Gardens.",
  ui_story_5026_50261502_38_dialog_content = "Do not worry. I'm quite good at cleaning up all stains, trash, and vermin.",
  ui_story_5026_50261502_39_dialog_content = "Which, of course, includes all the unwelcome guests in Cloud Gardens.",
  ui_story_5026_50261502_40_dialog_content = "You mean... You'll take care of all the Eclipsites?",
  ui_story_5026_50261502_41_dialog_content = "Won't you accept my apology?",
  ui_story_5026_50261502_42_dialog_content = "I accept, of course. It's just—",
  ui_story_5026_50261502_43_dialog_content = "No need to say more. I just want to show my sincerity.",
  ui_story_5026_50261502_44_dialog_content = "(How come I feel like I've been played...)",
  ui_story_5026_50261502_45_dialog_content = "(But in a good way?)",
  ui_story_5026_50261502_46_dialog_content = "You must be tired.",
  ui_story_5026_50261502_47_dialog_content = "Sanae, please take these two to the Hyacinth Tower to rest. I've set the table there already.",
  ui_story_5026_50261502_48_dialog_content = "Yes, sir!",
  ui_story_5026_50261502_49_dialog_content = "Um... Mr. Navigator, Nina.",
  ui_story_5026_50261502_50_dialog_content = "I guess... have a cup of tea first?",
  ui_story_5026_50261601_1_dialog_content = "Such is the full report of my trip to Cloud Gardens.",
  ui_story_5026_50261601_2_dialog_content = "The mission failed because of my own recklessness. I have no excuse.",
  ui_story_5026_50261601_3_dialog_content = "But I trust Miss Nina to make her own choices.",
  ui_story_5026_50261601_4_dialog_content = "Her determination and hard work, passion and persistence, are just like you.",
  ui_story_5026_50261601_5_dialog_content = "Minos...",
  ui_story_5026_50261601_6_dialog_content = "Yes, sir?",
  ui_story_5026_50261601_7_dialog_content = "When Nina was young, she'd run across half the courtyard just to show me a pretty flower she'd found.",
  ui_story_5026_50261601_8_dialog_content = "But after she grew up, she wouldn't even let me buy her any of her work.",
  ui_story_5026_50261601_9_dialog_content = "Is it so wrong for me to want to have something that she designed and crafted by herself?",
  ui_story_5026_50261601_10_dialog_content = "I wanted to have at least two sets of each kind and color for myself... One set for collection, the other set for actual use.",
  ui_story_5026_50261601_11_dialog_content = "Plus one more set to flaunt in front of Istvan.",
  ui_story_5026_50261601_12_dialog_content = "And three additional sets, just in case something gets damaged or lost in an accident.",
  ui_story_5026_50261601_13_dialog_content = "And sending someone to buy them for me in secret wasn't that much of an issue...",
  ui_story_5026_50261601_14_dialog_content = "Letting her find out was the only mistake I made.",
  ui_story_5026_50261601_15_dialog_content = "I knew it! You really haven't reflected upon what you did at all!",
  ui_story_5026_50261601_16_dialog_content = "Nina? You're back? Minos, are my eyes deceiving me?",
  ui_story_5026_50261601_17_dialog_content = "No, they are not, Master.",
  ui_story_5026_50261601_18_dialog_content = "The only reason I didn't want you to buy my creations is that you...",
  ui_story_5026_50261601_19_dialog_content = "You always want to go around flaunting my half-decent creations at every social gathering!",
  ui_story_5026_50261601_20_dialog_content = "It's so embarrassing!",
  ui_story_5026_50261601_21_dialog_content = "You're being too modest, my dear. I've never been anything but truthful in my flattery.",
  ui_story_5026_50261601_22_dialog_content = "And, was it necessary to completely buy out my shop?",
  ui_story_5026_50261601_23_dialog_content = "All our guards and escorts deserve to have such aesthetic and practical weapons.",
  ui_story_5026_50261601_24_dialog_content = "I just wanted to make you proud by doing better than Bethel...",
  ui_story_5026_50261601_25_dialog_content = "Minos was already extremely helpful to you when he was my age, wasn't he?",
  ui_story_5026_50261601_26_dialog_content = "You don't need to prove anything to me or compare yourself with anyone else.",
  ui_story_5026_50261601_27_dialog_content = "I've been proud of you since the moment of your birth.",
  ui_story_5026_50261601_28_dialog_content = "But there are other reasons I want to be successful too!",
  ui_story_5026_50261601_29_dialog_content = "I want my designs to become a part of everyday people's lives.",
  ui_story_5026_50261601_30_dialog_content = "In order to achieve that, I need real customer feedback, be it good or bad.",
  ui_story_5026_50261601_31_dialog_content = "That's the only way I can push my business forward.",
  ui_story_5026_50261601_32_dialog_content = "<anim type=Shake>Nina... You've really all grown up...</anim>",
  ui_story_5026_50261601_33_dialog_content = "<size=45>W-Why are you crying?</size>Papa, why are you so dramatic... You're embarrassing me.",
  ui_story_5026_50261601_34_dialog_content = "I just wish your mother could've heard what you just said.",
  ui_story_5026_50261601_35_dialog_content = "Oh, did I tell you I met this interesting Caelestite in Eraveil?",
  ui_story_5026_50261601_36_dialog_content = "If it weren't for him, I wouldn't have realized my flaws and immaturity when it comes to starting a business.",
  ui_story_5026_50261601_37_dialog_content = "I also wouldn't have realized I needed time to think and calm down, and to be honest with you about my feelings.",
  ui_story_5026_50261601_38_dialog_content = "The way he tried desperately to grasp something with his own hands...",
  ui_story_5026_50261601_39_dialog_content = "It gave me a glimpse of how you see me.",
  ui_story_5026_50261601_40_dialog_content = "Hmph! And you! Although I realized your true motives right away, I must say this!",
  ui_story_5026_50261601_41_dialog_content = "The way you taunted me, Minos, you really are good at pissing me off!",
  ui_story_5026_50261601_42_dialog_content = "Thank you for your compliment.",
  ui_story_5026_50261601_43_dialog_content = "That wasn't a compliment!",
  ui_story_5026_50261601_44_dialog_content = "Fine... I guess it is in a way.",
  ui_story_5026_50261601_45_dialog_content = "The Caelestite also keeps in his company a bunch of adorable Chubbs. Too bad I couldn't bring one back with me...",
  ui_story_5026_50261601_46_dialog_content = "And Sanae taught me how to catch fish! Also...",
  ui_story_5026_50261601_47_dialog_content = "Oh! Let me get out of what I'm wearing now. I'll be right back! Keep your schedule clear for me!",
  ui_story_5026_50261601_48_dialog_content = "Minos.",
  ui_story_5026_50261601_49_dialog_content = "Yes, sir?",
  ui_story_5026_50261601_50_dialog_content = "Who is this PlayerName?",
  ui_story_5026_50261601_51_dialog_content = "PlayerName may be young, but nevertheless, is a person of good character.",
  ui_story_5026_50261601_52_dialog_content = "Hmph! I don't buy into the Last Caelestite being a pacifist.",
  ui_story_5026_50261601_53_dialog_content = "Their innate ability makes it impossible for them to avoid getting embroiled in worldly matters.",
  ui_story_5026_50261601_54_dialog_content = "Honesty and goodness are not enough to guarantee survival in this world.",
  ui_story_5026_50261601_55_dialog_content = "You are right.",
  ui_story_5026_50261601_56_dialog_content = "The only way to maintain peace is to be the one holding the bigger stick.",
  ui_story_5026_50261601_57_dialog_content = "Or... by being on the side of the one holding the bigger stick.",
  ui_story_5026_50261601_58_dialog_content = "Never mind all that... I'm retired. I'll leave these worldly concerns to the Shadowlord. More importantly...",
  ui_story_5026_50261601_59_dialog_content = "My dear Nina seems to hold this Caelestite in high regard and cares for him. Is that true?",
  ui_story_5026_50261601_60_dialog_content = "As usual, all males in contact with Miss Nina are thoroughly investigated and observed.",
  ui_story_5026_50261601_61_dialog_content = "You have three minutes. I want all information related to that kid, including anything that might have appeared in the Umbraton Daily.",
  ui_story_5026_50261601_62_dialog_content = "As you wish.",
  ui_story_5026_50261601_63_dialog_content = "It's so quiet.",
  ui_story_5026_50261601_64_dialog_content = "(Not long after Minos left, Nina and Sanae also returned to Umbraton.)",
  ui_story_5026_50261601_65_dialog_content = "(I hope Nina can make peace with her father.)",
  ui_story_5026_50261601_66_dialog_content = "(Even though she still hasn't given up on that world domination plan of hers...)",
  ui_story_5026_50261601_67_dialog_content = "There are many things I need to figure out to integrate your \"safe haven\" idea with my plan.",
  ui_story_5026_50261601_68_dialog_content = "That was the reason why you rejected my plan initially, right?",
  ui_story_5026_50261601_69_dialog_content = "Being unable to earn the trust of my partner shows how immature I am.",
  ui_story_5026_50261601_70_dialog_content = "If that's so, I can't waste my time in this leisurely place anymore.",
  ui_story_5026_50261601_71_dialog_content = "I've decided to return home and learn business management from my father.",
  ui_story_5026_50261601_72_dialog_content = "But I promise you, I'll be back to request to work with you once I've learned all I can.",
  ui_story_5026_50261601_73_dialog_content = "D-Don't you dare forget!",
  ui_story_5026_50261601_74_dialog_content = "(Did Minos decide to tell me who Nina was because he saw my influence on her?)",
  ui_story_5026_50261601_75_dialog_content = "(If so... Then he wasn't only testing Nina, but also me...)",
  ui_story_5026_50261601_76_dialog_content = "(Maybe it had been his plan all along since the moment we met.)",
  ui_story_5026_50261601_77_dialog_content = "(How terrifying this butler is...)",
  ui_story_5026_50261601_78_dialog_content = "(In the end, I didn't manage to recruit a manager, but the Chubbs should be able to help me take care of Cloud Gardens.)",
  ui_story_5026_50261601_79_dialog_content = "(I've also learned quite a bit since I activated the Hyacinth Tower's defense system.)",
  ui_story_5026_50261601_80_dialog_content = "Now, then, I should get started on tasks around Cloud Gardens.",
  ui_story_5026_50261601_81_dialog_content = "First, that... what was it called again, an employee roster?",
  ui_story_5026_50261601_82_dialog_content = "Why are you alone here, PlayerName? Where's Nina and everybody else?",
  ui_story_5026_50261601_83_dialog_content = "A lot of friends of yours were willing to help out after hearing about your situation.",
  ui_story_5026_50261601_84_dialog_content = "Even though most of them couldn't make it due to previous engagements, I still managed to recruit some help.",
  ui_story_5026_50261601_85_dialog_content = "But it looks like you've taken care of the Eclipsites already.",
  ui_story_5026_50261601_86_dialog_content = "It's a long story... You didn't get my message, Bethel?",
  ui_story_5026_50261601_87_dialog_content = "I'll reimburse you for your transportation fees...",
  ui_story_5026_50261601_88_dialog_content = "Don't hesitate to contact me if you need work to be done in the future.",
  ui_story_5026_50261601_89_dialog_content = "You helped us during the Blue Lion Guild incident. I would very much like to have the chance to pay you back.",
  ui_story_5026_50261601_90_dialog_content = "I only did what I should have done. You don't owe me anything...",
  ui_story_5026_50261601_91_dialog_content = "You're too kind, PlayerName.",
  ui_story_5026_50261601_92_dialog_content = "Think of it like this, then: Helping the Last Caelestite rebuild his home and settle in is good for the image of the White Flame Mercenaries.",
  ui_story_5026_50261601_93_dialog_content = "A win-win, if you will.",
  ui_story_5026_50261601_94_dialog_content = "I see. Thanks for your help in advance, then.",
  ui_story_5026_50261601_95_dialog_content = "Oh, are all the jobs taken already?",
  ui_story_5026_50261601_96_dialog_content = "Since I'm here, I might as well do some business... I think a good painting would go well with your new home, PlayerName.",
  ui_story_5026_50261601_97_dialog_content = "As a boss, you need some art to make this place more sensual and show off your taste.",
  ui_story_5026_50261601_97X1_dialog_content = "If you're not into paintings, how about a statue by a currently trending artist in Umbraton?",
  ui_story_5026_50261601_97X2_dialog_content = "Tsk, as a canine myself, I can't help but admit that he's more endowed in the looks department.",
  ui_story_5026_50261601_98_dialog_content = "Thanks, but no thanks.",
  ui_story_5026_50261601_99_dialog_content = "Don't say that! Take a look at this brochure. These are all great paintings by renowned artists...",
  ui_story_5026_50261601_100_dialog_content = "Wow!",
  ui_story_5026_50261601_101_dialog_content = "Is this Puppy's home? So roomy!",
  ui_story_5026_50261601_102_dialog_content = "Not Puppy's, but PlayerName's.",
  ui_story_5026_50261601_103_dialog_content = "Puppy's new home is more spacious than the Colossus? I'd love to run around here!",
  ui_story_5026_50261601_104_dialog_content = "How about hide-and-seek?",
  ui_story_5026_50261601_105_dialog_content = "Let's all play hide-and-seek!",
  ui_story_5026_50261601_106_dialog_content = "Watch it, you two! Don't run into things!",
  ui_story_5026_50261601_107_dialog_content = "Feel free to crash into those two profiteers, but watch the relics. This place is an ancient Caelestite ruin.",
  ui_story_5026_50261601_108_dialog_content = "Caelestite relics are quite rare even in Umbraton. I imagine each of them would make quite a display in my future shop.",
  ui_story_5026_50261601_109_dialog_content = "There's some stuff in the Museum, but I don't know if they count as relics.",
  ui_story_5026_50261601_110_dialog_content = "Even though it seems like we don't have a job anymore, it was worth making this journey just to be able to look at your collection.",
  ui_story_5026_50261601_111_dialog_content = "I can show you the way! Chubb!",
  ui_story_5026_50261601_112_dialog_content = "Whoa, look at that fine ratio... I sense something precious about you.",
  ui_story_5026_50261601_113_dialog_content = "Chubb?",
  ui_story_5026_50261601_114_dialog_content = "Never mind the Museum. Mind if I check you out for a bit?",
  ui_story_5026_50261601_115_dialog_content = "Geez, that moment of peace just now was like a dream...",
  ui_story_5026_50261601_116_dialog_content = "Nothing about you is ever boring, brave Navigator.",
  ui_story_5026_50261601_117_dialog_content = "Kleken!",
  ui_story_5026_50261601_118_dialog_content = "Where out on the raging sea will this new ark take you?",
  ui_story_5026_50261601_119_dialog_content = "The gardens of the sky diving deep into the ocean must be a view to behold!",
  ui_story_5026_50261601_120_dialog_content = "I'll do my best to never ever let that happen...",
  ui_story_5026_50261601_121_dialog_content = "Ha... What crazy thing is he talking about this time?",
  ui_story_5026_50261601_122_dialog_content = "You too, PlayerName. You still look as clumsy as always.",
  ui_story_5026_50261601_123_dialog_content = "Hydrad? I didn't think you'd be here too—",
  ui_story_5026_50261601_124_dialog_content = "Bye.",
  ui_story_5026_50261601_125_dialog_content = "You just got here!",
  ui_story_5026_50261601_126_dialog_content = "It's not like I wanted to come! That stupid octopus lied to me about how the boss needed me here for a job.",
  ui_story_5026_50261601_127_dialog_content = "It's too wide and open here. It's making the Shadow Wolves restless, like those dogs over there.",
  ui_story_5026_50261601_128_dialog_content = "It can't be helped. It's in our nature!",
  ui_story_5026_50261601_129_dialog_content = "<size=40>Come on! Come on! Let's play hide-and-seek!</size>",
  ui_story_5026_50261601_130_dialog_content = "<size=45>Fufufu!</size>",
  ui_story_5026_50261601_131_dialog_content = "<size=50>It's so noisy! Get away from me!</size>",
  ui_story_5026_50261601_132_dialog_content = "... I didn't expect things to turn out like this.",
  ui_story_5026_50261601_133_dialog_content = "Color me shocked. Without a job to do, Umbraton's professionals are just a bunch of problematic children.",
  ui_story_5026_50261601_134_dialog_content = "Isn't it nice to see puppies playing and chasing each other around in a field?",
  ui_story_5026_50261601_135_dialog_content = "Looks like this commotion isn't going to end for a while.",
  ui_story_5026_50261601_136_dialog_content = "Er... If you guys aren't in a hurry...",
  ui_story_5026_50261601_137_dialog_content = "Why don't you sit down for some tea?",
  ui_story_5026_50261601_138_dialog_content = "<color=#e8d9bb>On the Bridge of Soroz, a few days later</color>",
  ui_story_5026_50261601_139_dialog_content = "So... you went through all these things while we were gone, huh?",
  ui_story_5026_50261601_140_dialog_content = "I'm happy for you, but I also feel a bit down for some reason.",
  ui_story_5026_50261601_141_dialog_content = "Vice...",
  ui_story_5026_50261601_142_dialog_content = "You better show me the Chubb Sword if you ever get the chance to make it again in the future!",
  ui_story_5026_50261601_143_dialog_content = "You're feeling down because of that!?",
  ui_story_5026_50261601_144_dialog_content = "A force field... I didn't know the Hyacinth Tower could do that.",
  ui_story_5026_50261601_145_dialog_content = "Cloud Gardens security was something that had been concerning me.",
  ui_story_5026_50261601_146_dialog_content = "Thankfully, everything got resolved before any permanent damage could done.",
  ui_story_5026_50261601_147_dialog_content = "You defended your home on your own. Good job, PlayerName.",
  ui_story_5026_50261601_148_dialog_content = "Thank you, Carleen.",
  ui_story_5026_50261601_149_dialog_content = "But I didn't do it alone. I couldn't have done it without Nina and everyone else.",
  ui_story_5026_50261601_150_dialog_content = "Just like Cloud Gardens would not be here right now without everyone's help.",
  ui_story_5026_50261601_151_dialog_content = "...",
  ui_story_5026_50261601_152_dialog_content = "After learning what I did about the Caelestites from the Obelisk of Return and Cloud Gardens...",
  ui_story_5026_50261601_153_dialog_content = "I became disenchanted with my people and doubted myself.",
  ui_story_5026_50261601_154_dialog_content = "But fighting alongside you guys and all the other Aurorians made me realize something.",
  ui_story_5026_50261601_155_dialog_content = "It's not my lineage or my ability that defines who I am.",
  ui_story_5026_50261601_156_dialog_content = "It's my own will and choices.",
  ui_story_5026_50261601_157_dialog_content = "With all of you by my side, I won't make decisions that I'll come to regret.",
  ui_story_5026_50261601_158_dialog_content = "Eraveil's fate won't repeat itself.",
  ui_story_5026_50261601_159_dialog_content = "Seclusion cannot protect us or bring us peace.",
  ui_story_5026_50261601_160_dialog_content = "Only having friends can do that.",
  ui_story_5026_50261601_161_dialog_content = "I want to live on this piece of land with my Aurorian friends.",
  ui_story_5026_50261601_162_dialog_content = "I want it to be a safe haven where all can find peace.",
  ui_story_5026_50261601_163_dialog_content = "A <color=#FFB400>real home</color>.",
  ui_story_5026_50261601_164_dialog_content = "PlayerName...",
  ui_story_5026_50261601_165_dialog_content = "Heh, nice speech. You're finally starting to sound like a boss.",
  ui_story_5026_50261601_166_dialog_content = "R-Really?",
  ui_story_5026_50261601_167_dialog_content = "Oh, by the way, Minos taught the Chubbs how to maintain Cloud Gardens more effectively.",
  ui_story_5026_50261601_168_dialog_content = "Bethel also said the guild wishes to collaborate with me and sell Cloud Gardens' goods in Umbraton.",
  ui_story_5026_50261601_169_dialog_content = "If all goes well, soon we won't have to worry about Nightium.",
  ui_story_5026_50261601_170_dialog_content = "Oh, about that...",
